#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct SkillAlias {
    pub raw: String,
    pub canonical: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct SkillFamilyDefinition {
    pub family_name: String,
    pub canonical_family: String,
    pub aliases: Vec<SkillAlias>,
    pub members: Vec<SkillRecord>,
}

pub trait SkillCanonicalizer {
    fn canonicalize(&self, raw: &str) -> String;
}

#[derive(Debug, Default, Clone, Copy)]
pub struct LowercaseTrimCanonicalizer;

impl NamedComponent for LowercaseTrimCanonicalizer {
    fn component_name(&self) -> &'static str {
        "lowercase-trim-canonicalizer"
    }
}

impl SkillCanonicalizer for LowercaseTrimCanonicalizer {
    fn canonicalize(&self, raw: &str) -> String {
        raw.split_whitespace()
            .collect::<Vec<_>>()
            .join(" ")
            .to_lowercase()
    }
}

pub fn canonicalize_record(
    record: &SkillRecord,
    canonicalizer: &impl SkillCanonicalizer,
) -> SkillRecord {
    let mut updated = record.clone();
    updated.canonical_name = canonicalizer.canonicalize(&record.canonical_name);
    updated.aliases = record
        .aliases
        .iter()
        .map(|alias| canonicalizer.canonicalize(alias))
        .collect();
    updated
}

