pub fn canonicalize_low_boost_recovery_slice_v1(
    slice: &ReplaySliceRef,
) -> Result<LowBoostRecoveryCanonicalBundleV1, LowBoostRecoveryCanonicalizationError> {
    ensure_supported_low_boost_slice(slice)?;

    let canonical_state = LowBoostRecoveryCanonicalStateV1 {
        slice_id: slice.slice_id.clone(),
        source_replay: slice.source_replay.clone(),
        subject: slice.subject.clone(),
        frame_window: slice.frame_window.clone(),
        raw_state_window_ref: slice.raw_state_window_ref.clone(),
        orientation_note: LowBoostRecoveryCanonicalOrientationNoteV1::SubjectAnchoredWindowOnly,
        subject_state_envelope: LowBoostRecoverySubjectStateEnvelopeV1 {
            subject: slice.subject.clone(),
            frame_window: slice.frame_window.clone(),
            semantics: LowBoostRecoveryEnvelopeSemanticsV1::RawStateWindowReferenceOnly,
        },
        environment_state_envelope: LowBoostRecoveryEnvironmentStateEnvelopeV1 {
            frame_window: slice.frame_window.clone(),
            semantics: LowBoostRecoveryEnvelopeSemanticsV1::RawStateWindowReferenceOnly,
        },
        canonicalization_notes: vec![
            LowBoostRecoveryCanonicalNoteV1::BoostAmountUnresolved,
            LowBoostRecoveryCanonicalNoteV1::ContactTruthUnresolved,
            LowBoostRecoveryCanonicalNoteV1::RecoverySuccessUnresolved,
            LowBoostRecoveryCanonicalNoteV1::ReplayOrientationNormalizationDeferred,
        ],
    };

    let event_contact_graph = LowBoostRecoveryEventContactGraphV1 {
        slice_id: slice.slice_id.clone(),
        frame_window: slice.frame_window.clone(),
        nodes: vec![
            LowBoostRecoveryEventNodeV1 {
                node_id: 0,
                frame_index: slice.frame_window.start,
                kind: LowBoostRecoveryEventNodeKindV1::SliceWindowStart,
            },
            LowBoostRecoveryEventNodeV1 {
                node_id: 1,
                frame_index: slice.frame_window.end_exclusive,
                kind: LowBoostRecoveryEventNodeKindV1::SliceWindowEndExclusive,
            },
        ],
        edges: vec![LowBoostRecoveryEventEdgeV1 {
            from_node_id: 0,
            to_node_id: 1,
            kind: LowBoostRecoveryEventEdgeKindV1::ObservedSliceWindow,
        }],
        contact_semantics: LowBoostRecoveryContactSemanticsV1::UnresolvedFromReplaySliceContract,
    };

    let phase_plan = LowBoostRecoveryPhasePlanV1 {
        slice_id: slice.slice_id.clone(),
        phases: vec![LowBoostRecoveryPhaseV1 {
            phase_id: 0,
            label: LowBoostRecoveryPhaseLabelV1::CandidateRecoveryWindow,
            start: slice.frame_window.start,
            end_exclusive: slice.frame_window.end_exclusive,
        }],
    };

    Ok(LowBoostRecoveryCanonicalBundleV1 {
        canonical_state,
        event_contact_graph,
        phase_plan,
    })
}

pub fn solve_low_boost_recovery_parameters_v1(
    bundle: &LowBoostRecoveryCanonicalBundleV1,
) -> Result<LowBoostRecoveryParameterBundleV1, LowBoostRecoveryParameterVariationError> {
    validate_low_boost_recovery_canonical_bundle(bundle)?;

    let phase = &bundle.phase_plan.phases[0];
    let duration_frames = phase.end_exclusive.get() - phase.start.get();
    let trim_budget = u32::from(duration_frames > 1);

    Ok(LowBoostRecoveryParameterBundleV1 {
        slice_id: bundle.canonical_state.slice_id.clone(),
        family: ReplaySliceFamilyHint::LowBoostRecovery,
        source_replay: bundle.canonical_state.source_replay.clone(),
        subject: bundle.canonical_state.subject.clone(),
        raw_state_window_ref: bundle.canonical_state.raw_state_window_ref.clone(),
        phase_window_link: LowBoostRecoveryPhaseWindowLinkV1 {
            phase_id: phase.phase_id,
            phase_label: phase.label.clone(),
            window: TimeWindow {
                start: phase.start,
                end_exclusive: phase.end_exclusive,
            },
        },
        recovery_window_interpretation:
            LowBoostRecoveryWindowInterpretationV1::CandidateRecoveryWindowOnly,
        observed_window_duration_frames: LowBoostRecoveryFrameRangeV1 {
            min_inclusive: duration_frames,
            max_inclusive: duration_frames,
        },
        boundary_trim_budget_frames: LowBoostRecoveryFrameRangeV1 {
            min_inclusive: 0,
            max_inclusive: trim_budget,
        },
        parameter_notes: vec![
            LowBoostRecoveryParameterNoteV1::ObservedWindowDerivedFromCanonicalPhase,
            LowBoostRecoveryParameterNoteV1::BoundaryVariationLimitedToSingleFrameTrims,
        ],
        unresolved_assumptions: derive_low_boost_unresolved_assumptions(bundle),
    })
}

pub fn generate_low_boost_recovery_variants_v1(
    parameters: &LowBoostRecoveryParameterBundleV1,
) -> Vec<LowBoostRecoveryGeneratedVariantV1> {
    let mut variants = vec![build_low_boost_variant(
        parameters,
        LowBoostRecoveryWindowOverrideV1 {
            trim_start_frames: 0,
            trim_end_frames: 0,
        },
        LowBoostRecoveryDifficultyHintV1::ReferenceSeedWindow,
        LowBoostRecoveryGenerationReasonV1::PreserveObservedWindow,
        "exact",
    )];

    if parameters.boundary_trim_budget_frames.max_inclusive >= 1
        && parameters.phase_window_link.window.start.get() + 1
            < parameters.phase_window_link.window.end_exclusive.get()
    {
        variants.push(build_low_boost_variant(
            parameters,
            LowBoostRecoveryWindowOverrideV1 {
                trim_start_frames: 1,
                trim_end_frames: 0,
            },
            LowBoostRecoveryDifficultyHintV1::StricterStartBoundary,
            LowBoostRecoveryGenerationReasonV1::ProbeStartBoundaryAmbiguity,
            "trim_start_1",
        ));
        variants.push(build_low_boost_variant(
            parameters,
            LowBoostRecoveryWindowOverrideV1 {
                trim_start_frames: 0,
                trim_end_frames: 1,
            },
            LowBoostRecoveryDifficultyHintV1::StricterEndBoundary,
            LowBoostRecoveryGenerationReasonV1::ProbeEndBoundaryAmbiguity,
            "trim_end_1",
        ));
    }

    variants
}

pub fn validate_low_boost_recovery_candidate_v1(
    parameters: &LowBoostRecoveryParameterBundleV1,
    variants: &[LowBoostRecoveryGeneratedVariantV1],
) -> LowBoostRecoveryValidationResultV1 {
    let carried_unresolved_assumptions = parameters.unresolved_assumptions.clone();

    if parameter_bundle_is_malformed(parameters) {
        return LowBoostRecoveryValidationResultV1 {
            source_slice_id: parameters.slice_id.clone(),
            source_phase_id: parameters.phase_window_link.phase_id,
            reference_variant_id: None,
            evaluated_variant_ids: Vec::new(),
            decision: LowBoostRecoveryValidationDecisionV1::Malformed,
            reason: LowBoostRecoveryValidationReasonV1::MalformedParameterBundle,
            confidence_band: LowBoostRecoveryConfidenceBandV1::InsufficientEvidence,
            carried_unresolved_assumptions,
            validator_notes: Vec::new(),
        };
    }

    let Some(classified_variants) = classify_low_boost_variants(parameters, variants) else {
        return LowBoostRecoveryValidationResultV1 {
            source_slice_id: parameters.slice_id.clone(),
            source_phase_id: parameters.phase_window_link.phase_id,
            reference_variant_id: None,
            evaluated_variant_ids: Vec::new(),
            decision: LowBoostRecoveryValidationDecisionV1::Malformed,
            reason: LowBoostRecoveryValidationReasonV1::MalformedVariantSet,
            confidence_band: LowBoostRecoveryConfidenceBandV1::InsufficientEvidence,
            carried_unresolved_assumptions,
            validator_notes: Vec::new(),
        };
    };

    let mut validator_notes = vec![
        LowBoostRecoveryValidationNoteV1::ReferenceVariantPresent,
        LowBoostRecoveryValidationNoteV1::KnownUnresolvedAssumptionsCarriedForward,
    ];
    let mut evaluated_variant_ids = vec![classified_variants.exact.variant_id.clone()];

    if let Some(start_trim) = &classified_variants.start_trim {
        validator_notes.push(LowBoostRecoveryValidationNoteV1::StartTrimVariantPresent);
        evaluated_variant_ids.push(start_trim.variant_id.clone());
    }

    if let Some(end_trim) = &classified_variants.end_trim {
        validator_notes.push(LowBoostRecoveryValidationNoteV1::EndTrimVariantPresent);
        evaluated_variant_ids.push(end_trim.variant_id.clone());
    }

    let exact_duration = window_duration_frames(&classified_variants.exact.variant_window);
    if exact_duration < 2 {
        validator_notes
            .push(LowBoostRecoveryValidationNoteV1::ExactWindowFailsMinimumEvidenceFloor);
        return LowBoostRecoveryValidationResultV1 {
            source_slice_id: parameters.slice_id.clone(),
            source_phase_id: parameters.phase_window_link.phase_id,
            reference_variant_id: Some(classified_variants.exact.variant_id.clone()),
            evaluated_variant_ids,
            decision: LowBoostRecoveryValidationDecisionV1::Reject,
            reason: LowBoostRecoveryValidationReasonV1::ExactWindowBelowMinimumEvidenceFloor,
            confidence_band: LowBoostRecoveryConfidenceBandV1::InsufficientEvidence,
            carried_unresolved_assumptions,
            validator_notes,
        };
    }

    validator_notes.push(LowBoostRecoveryValidationNoteV1::ExactWindowMeetsMinimumEvidenceFloor);

    let trimmed_durations = [
        classified_variants
            .start_trim
            .as_ref()
            .map(|variant| window_duration_frames(&variant.variant_window)),
        classified_variants
            .end_trim
            .as_ref()
            .map(|variant| window_duration_frames(&variant.variant_window)),
    ];

    if trimmed_durations
        .into_iter()
        .flatten()
        .any(|duration| duration < 2)
    {
        validator_notes.push(LowBoostRecoveryValidationNoteV1::TrimmedVariantsTooShortForStability);
        return LowBoostRecoveryValidationResultV1 {
            source_slice_id: parameters.slice_id.clone(),
            source_phase_id: parameters.phase_window_link.phase_id,
            reference_variant_id: Some(classified_variants.exact.variant_id.clone()),
            evaluated_variant_ids,
            decision: LowBoostRecoveryValidationDecisionV1::Abstain,
            reason: LowBoostRecoveryValidationReasonV1::BoundarySensitivityTooHigh,
            confidence_band: LowBoostRecoveryConfidenceBandV1::BoundarySensitive,
            carried_unresolved_assumptions,
            validator_notes,
        };
    }

    validator_notes.push(LowBoostRecoveryValidationNoteV1::TrimmedVariantsMeetStabilityFloor);
    LowBoostRecoveryValidationResultV1 {
        source_slice_id: parameters.slice_id.clone(),
        source_phase_id: parameters.phase_window_link.phase_id,
        reference_variant_id: Some(classified_variants.exact.variant_id.clone()),
        evaluated_variant_ids,
        decision: LowBoostRecoveryValidationDecisionV1::AcceptCandidate,
        reason: LowBoostRecoveryValidationReasonV1::ProvisionalCandidateAccepted,
        confidence_band: LowBoostRecoveryConfidenceBandV1::BoundaryStable,
        carried_unresolved_assumptions,
        validator_notes,
    }
}

