const LOW_BOOST_RECOVERY_BC_FILESYSTEM_EXPORT_EMISSION_ROOT_DIRECTORY_V1: &str =
    "low_boost_recovery_bc_v1";
const LOW_BOOST_RECOVERY_BC_FILESYSTEM_EXPORT_EMISSION_LANE_DIRECTORY_PREFIX_V1: &str =
    "recovery_context_lane_";
const LOW_BOOST_RECOVERY_BC_FILESYSTEM_EXPORT_EMISSION_SPECIMEN_FILE_STEM_PREFIX_V1: &str =
    "specimen_";
const LOW_BOOST_RECOVERY_BC_ACTUAL_FILESYSTEM_EMISSION_SPECIMEN_FILE_EXTENSION_V1: &str = "json";

pub fn build_low_boost_recovery_curriculum_export_shell_v1(
    parameters: &LowBoostRecoveryParameterBundleV1,
    variants: &[LowBoostRecoveryGeneratedVariantV1],
    validation: &LowBoostRecoveryValidationResultV1,
) -> Result<
    Option<LowBoostRecoveryCurriculumExportShellV1>,
    LowBoostRecoveryCurriculumExportShellError,
> {
    if parameter_bundle_is_malformed(parameters) {
        return Err(LowBoostRecoveryCurriculumExportShellError::ParameterBundleMalformed);
    }

    let Some(classified_variants) = classify_low_boost_variants(parameters, variants) else {
        return Err(LowBoostRecoveryCurriculumExportShellError::VariantSetMalformed);
    };

    if validation.source_slice_id != parameters.slice_id {
        return Err(
            LowBoostRecoveryCurriculumExportShellError::ValidationResultInconsistent {
                detail: "source_slice_id does not match parameter bundle",
            },
        );
    }

    if validation.source_phase_id != parameters.phase_window_link.phase_id {
        return Err(
            LowBoostRecoveryCurriculumExportShellError::ValidationResultInconsistent {
                detail: "source_phase_id does not match parameter bundle",
            },
        );
    }

    if validation.carried_unresolved_assumptions != parameters.unresolved_assumptions {
        return Err(
            LowBoostRecoveryCurriculumExportShellError::ValidationResultInconsistent {
                detail: "carried_unresolved_assumptions do not match parameter bundle",
            },
        );
    }

    if validation.decision != LowBoostRecoveryValidationDecisionV1::AcceptCandidate {
        return Ok(None);
    }

    if validation.reason != LowBoostRecoveryValidationReasonV1::ProvisionalCandidateAccepted {
        return Err(
            LowBoostRecoveryCurriculumExportShellError::ValidationResultInconsistent {
                detail: "accept_candidate requires provisional acceptance reason",
            },
        );
    }

    if validation.confidence_band != LowBoostRecoveryConfidenceBandV1::BoundaryStable {
        return Err(
            LowBoostRecoveryCurriculumExportShellError::ValidationResultInconsistent {
                detail: "accept_candidate requires boundary_stable confidence",
            },
        );
    }

    let Some(reference_variant_id) = &validation.reference_variant_id else {
        return Err(
            LowBoostRecoveryCurriculumExportShellError::ValidationResultInconsistent {
                detail: "accept_candidate requires reference_variant_id",
            },
        );
    };

    if reference_variant_id != &classified_variants.exact.variant_id {
        return Err(
            LowBoostRecoveryCurriculumExportShellError::ValidationResultInconsistent {
                detail: "reference_variant_id does not match exact variant lineage",
            },
        );
    }

    let expected_evaluated_variant_ids = expected_evaluated_variant_ids(&classified_variants);
    if validation.evaluated_variant_ids != expected_evaluated_variant_ids {
        return Err(
            LowBoostRecoveryCurriculumExportShellError::ValidationResultInconsistent {
                detail: "evaluated_variant_ids do not match classified variant lineage",
            },
        );
    }

    if !validation
        .validator_notes
        .contains(&LowBoostRecoveryValidationNoteV1::ReferenceVariantPresent)
        || !validation
            .validator_notes
            .contains(&LowBoostRecoveryValidationNoteV1::KnownUnresolvedAssumptionsCarriedForward)
        || !validation
            .validator_notes
            .contains(&LowBoostRecoveryValidationNoteV1::ExactWindowMeetsMinimumEvidenceFloor)
        || !validation
            .validator_notes
            .contains(&LowBoostRecoveryValidationNoteV1::TrimmedVariantsMeetStabilityFloor)
    {
        return Err(
            LowBoostRecoveryCurriculumExportShellError::ValidationResultInconsistent {
                detail: "accept_candidate is missing required validator notes",
            },
        );
    }

    Ok(Some(LowBoostRecoveryCurriculumExportShellV1 {
        family: ReplaySliceFamilyHint::LowBoostRecovery,
        source_slice_id: parameters.slice_id.clone(),
        source_replay: parameters.source_replay.clone(),
        source_subject: parameters.subject.clone(),
        source_raw_state_window_ref: parameters.raw_state_window_ref.clone(),
        source_phase_id: parameters.phase_window_link.phase_id,
        source_phase_window: parameters.phase_window_link.window.clone(),
        accepted_reference_variant_id: reference_variant_id.clone(),
        accepted_reference_variant_window: classified_variants.exact.variant_window.clone(),
        evaluated_variant_ids: validation.evaluated_variant_ids.clone(),
        accepted_decision: validation.decision.clone(),
        decision_reason: validation.reason.clone(),
        confidence_band: validation.confidence_band.clone(),
        carried_unresolved_assumptions: validation.carried_unresolved_assumptions.clone(),
        shell_notes: vec![
            LowBoostRecoveryCurriculumExportShellNoteV1::AcceptedCandidateOnly,
            LowBoostRecoveryCurriculumExportShellNoteV1::ProvisionalAcceptanceOnly,
            LowBoostRecoveryCurriculumExportShellNoteV1::UnresolvedAssumptionsCarriedForward,
        ],
        consumer_hint: LowBoostRecoveryCurriculumExportConsumerHintV1::EvalHarnessOnly,
    }))
}

pub fn evaluate_low_boost_recovery_curriculum_export_shell_v1(
    shell: &LowBoostRecoveryCurriculumExportShellV1,
) -> LowBoostRecoveryEvalResultV1 {
    let core_input_present = low_boost_eval_core_input_present(shell);
    let lineage_complete = low_boost_eval_lineage_complete(shell);
    let accepted_shell_complete = low_boost_eval_shell_complete(shell);
    let bounded_evidence_consistency = low_boost_eval_bounded_evidence_consistency(shell);
    let unresolved_burden_visibility = low_boost_eval_unresolved_burden_visibility(shell);
    let reference_window_availability = low_boost_eval_reference_window_availability(shell);

    let metric_summary = LowBoostRecoveryEvalMetricSummaryV1 {
        lineage_completeness: lineage_complete,
        accepted_shell_completeness: accepted_shell_complete,
        bounded_evidence_consistency,
        unresolved_burden_visibility,
        reference_window_availability,
    };

    let eval_status = if !core_input_present || !reference_window_availability {
        LowBoostRecoveryEvalStatusV1::UnusableInput
    } else if !lineage_complete {
        LowBoostRecoveryEvalStatusV1::ShellPresent
    } else if !accepted_shell_complete
        || !bounded_evidence_consistency
        || !unresolved_burden_visibility
    {
        LowBoostRecoveryEvalStatusV1::ShellAuditable
    } else {
        LowBoostRecoveryEvalStatusV1::ShellReadyForFutureConsumer
    };

    let mut eval_notes = Vec::new();
    if lineage_complete {
        eval_notes.push(LowBoostRecoveryEvalNoteV1::SourceLineagePresent);
        eval_notes.push(LowBoostRecoveryEvalNoteV1::AcceptedReferenceVariantLineagePresent);
    }
    if accepted_shell_complete {
        eval_notes.push(LowBoostRecoveryEvalNoteV1::AcceptedShellContractSatisfied);
    }
    if bounded_evidence_consistency {
        eval_notes.push(LowBoostRecoveryEvalNoteV1::BoundedEvidenceConsistent);
    }
    if unresolved_burden_visibility {
        eval_notes.push(LowBoostRecoveryEvalNoteV1::UnresolvedAssumptionsVisible);
    }
    if reference_window_availability {
        eval_notes.push(LowBoostRecoveryEvalNoteV1::ReferenceWindowAvailable);
    }
    if eval_status == LowBoostRecoveryEvalStatusV1::UnusableInput {
        eval_notes.push(LowBoostRecoveryEvalNoteV1::InputStructuralDriftDetected);
    }
    if eval_status != LowBoostRecoveryEvalStatusV1::ShellReadyForFutureConsumer {
        eval_notes.push(LowBoostRecoveryEvalNoteV1::FutureConsumerReadinessLimited);
    }

    LowBoostRecoveryEvalResultV1 {
        source_slice_id: shell.source_slice_id.clone(),
        source_phase_id: shell.source_phase_id,
        accepted_reference_variant_id: if shell.accepted_reference_variant_id.as_str().is_empty() {
            None
        } else {
            Some(shell.accepted_reference_variant_id.clone())
        },
        eval_status,
        eval_notes,
        metric_summary,
        carried_confidence_band: shell.confidence_band.clone(),
        carried_unresolved_assumptions: shell.carried_unresolved_assumptions.clone(),
    }
}

pub fn plan_low_boost_recovery_consumer_bc_boundary_v1(
    shell: &LowBoostRecoveryCurriculumExportShellV1,
    eval: &LowBoostRecoveryEvalResultV1,
) -> LowBoostRecoveryConsumerPlanningResultV1 {
    let shell_boundary_present = low_boost_eval_core_input_present(shell);
    let shell_eval_aligned = low_boost_consumer_planning_shell_eval_aligned(shell, eval);
    let accepted_reference_variant_id = eval
        .accepted_reference_variant_id
        .clone()
        .filter(|variant_id| variant_id == &shell.accepted_reference_variant_id);

    let disposition = if !shell_boundary_present
        || !shell_eval_aligned
        || eval.eval_status == LowBoostRecoveryEvalStatusV1::UnusableInput
        || eval.eval_status == LowBoostRecoveryEvalStatusV1::ShellPresent
    {
        LowBoostRecoveryConsumerPlanningDispositionV1::NotBcCandidate
    } else if eval.eval_status == LowBoostRecoveryEvalStatusV1::ShellAuditable {
        LowBoostRecoveryConsumerPlanningDispositionV1::BcCandidateDeferred
    } else {
        LowBoostRecoveryConsumerPlanningDispositionV1::BcCandidateReadyForContractDefinition
    };

    let mut planning_notes = vec![
        LowBoostRecoveryConsumerPlanningNoteV1::BcMilestoneApproaching,
        LowBoostRecoveryConsumerPlanningNoteV1::PlanningOnlyNotBcUsefulnessProof,
    ];

    if shell_eval_aligned {
        planning_notes.push(LowBoostRecoveryConsumerPlanningNoteV1::ShellEvalBoundaryAligned);
        if accepted_reference_variant_id.is_some() {
            planning_notes.push(
                LowBoostRecoveryConsumerPlanningNoteV1::AcceptedReferenceVariantLineagePreserved,
            );
        }
        if matches_exactly_once(
            &eval.carried_unresolved_assumptions,
            &shell.carried_unresolved_assumptions,
        ) {
            planning_notes
                .push(LowBoostRecoveryConsumerPlanningNoteV1::UnresolvedAssumptionsCarriedForward);
        }
    }

    match disposition {
        LowBoostRecoveryConsumerPlanningDispositionV1::NotBcCandidate => {
            planning_notes.push(LowBoostRecoveryConsumerPlanningNoteV1::PlanningInputNotUsable);
        }
        LowBoostRecoveryConsumerPlanningDispositionV1::BcCandidateDeferred => {
            planning_notes.push(LowBoostRecoveryConsumerPlanningNoteV1::EvalReadinessLimited);
        }
        LowBoostRecoveryConsumerPlanningDispositionV1::BcCandidateReadyForContractDefinition => {
            planning_notes
                .push(LowBoostRecoveryConsumerPlanningNoteV1::ReadyForBcContractDefinitionOnly);
        }
    }

    LowBoostRecoveryConsumerPlanningResultV1 {
        source_slice_id: shell.source_slice_id.clone(),
        source_replay: shell.source_replay.clone(),
        source_subject: shell.source_subject.clone(),
        source_raw_state_window_ref: shell.source_raw_state_window_ref.clone(),
        source_phase_id: shell.source_phase_id,
        accepted_reference_variant_id,
        eval_readiness_status: eval.eval_status.clone(),
        carried_confidence_band: eval.carried_confidence_band.clone(),
        carried_unresolved_assumptions: eval.carried_unresolved_assumptions.clone(),
        disposition,
        planning_notes,
    }
}

pub fn define_low_boost_recovery_bc_contract_row_v1(
    shell: &LowBoostRecoveryCurriculumExportShellV1,
    planning: &LowBoostRecoveryConsumerPlanningResultV1,
) -> Result<Option<LowBoostRecoveryBcRowV1>, LowBoostRecoveryBcContractDefinitionError> {
    if planning.disposition
        != LowBoostRecoveryConsumerPlanningDispositionV1::BcCandidateReadyForContractDefinition
    {
        return Ok(None);
    }

    if !low_boost_bc_contract_shell_ready(shell) {
        return Err(
            LowBoostRecoveryBcContractDefinitionError::AcceptedShellMalformed {
                detail: "shell no longer satisfies the accepted low-boost-recovery boundary",
            },
        );
    }

    if planning.eval_readiness_status != LowBoostRecoveryEvalStatusV1::ShellReadyForFutureConsumer {
        return Err(
            LowBoostRecoveryBcContractDefinitionError::PlanningResultInconsistent {
                detail: "ready-for-contract-definition planning result requires shell_ready_for_future_consumer eval status",
            },
        );
    }

    if planning.source_slice_id != shell.source_slice_id {
        return Err(
            LowBoostRecoveryBcContractDefinitionError::PlanningResultInconsistent {
                detail: "source_slice_id does not match accepted shell",
            },
        );
    }

    if planning.source_replay != shell.source_replay {
        return Err(
            LowBoostRecoveryBcContractDefinitionError::PlanningResultInconsistent {
                detail: "source_replay does not match accepted shell",
            },
        );
    }

    if planning.source_subject != shell.source_subject {
        return Err(
            LowBoostRecoveryBcContractDefinitionError::PlanningResultInconsistent {
                detail: "source_subject does not match accepted shell",
            },
        );
    }

    if planning.source_raw_state_window_ref != shell.source_raw_state_window_ref {
        return Err(
            LowBoostRecoveryBcContractDefinitionError::PlanningResultInconsistent {
                detail: "source_raw_state_window_ref does not match accepted shell",
            },
        );
    }

    if planning.source_phase_id != shell.source_phase_id {
        return Err(
            LowBoostRecoveryBcContractDefinitionError::PlanningResultInconsistent {
                detail: "source_phase_id does not match accepted shell",
            },
        );
    }

    let Some(accepted_reference_variant_id) = planning.accepted_reference_variant_id.clone() else {
        return Err(
            LowBoostRecoveryBcContractDefinitionError::PlanningResultInconsistent {
                detail: "ready-for-contract-definition planning result requires accepted_reference_variant_id",
            },
        );
    };

    if accepted_reference_variant_id != shell.accepted_reference_variant_id {
        return Err(
            LowBoostRecoveryBcContractDefinitionError::PlanningResultInconsistent {
                detail: "accepted_reference_variant_id does not match accepted shell",
            },
        );
    }

    if planning.carried_confidence_band != shell.confidence_band {
        return Err(
            LowBoostRecoveryBcContractDefinitionError::PlanningResultInconsistent {
                detail: "carried_confidence_band does not match accepted shell",
            },
        );
    }

    if planning.carried_unresolved_assumptions != shell.carried_unresolved_assumptions {
        return Err(
            LowBoostRecoveryBcContractDefinitionError::PlanningResultInconsistent {
                detail: "carried_unresolved_assumptions do not match accepted shell",
            },
        );
    }

    Ok(Some(LowBoostRecoveryBcRowV1 {
        family: ReplaySliceFamilyHint::LowBoostRecovery,
        source_slice_id: planning.source_slice_id.clone(),
        source_replay: planning.source_replay.clone(),
        source_subject: planning.source_subject.clone(),
        source_raw_state_window_ref: planning.source_raw_state_window_ref.clone(),
        source_phase_id: planning.source_phase_id,
        accepted_reference_variant_id,
        supervision_window_role:
            LowBoostRecoveryBcSupervisionWindowRoleV1::AcceptedReferenceVariantWindow,
        observation_binding_kind:
            LowBoostRecoveryBcObservationBindingKindV1::AcceptedReferenceWindowFromRawStateWindowRef,
        target_binding_kind:
            LowBoostRecoveryBcTargetBindingKindV1::AcceptedReferenceVariantControlTargetDeferred,
        carried_confidence_band: planning.carried_confidence_band.clone(),
        carried_unresolved_assumptions: planning.carried_unresolved_assumptions.clone(),
        bc_contract_notes: vec![
            LowBoostRecoveryBcContractNoteV1::ContractDefinitionOnly,
            LowBoostRecoveryBcContractNoteV1::AcceptedShellPlanningBoundaryAligned,
            LowBoostRecoveryBcContractNoteV1::ObservationBindingDeferredToLaterSerialization,
            LowBoostRecoveryBcContractNoteV1::TargetBindingDeferredToLaterSerialization,
            LowBoostRecoveryBcContractNoteV1::ProvisionalConfidenceCarriedForward,
            LowBoostRecoveryBcContractNoteV1::UnresolvedAssumptionsCarriedForward,
            LowBoostRecoveryBcContractNoteV1::NotBcUsefulnessProof,
        ],
    }))
}

pub fn serialize_low_boost_recovery_bc_artifact_v1(
    row: &LowBoostRecoveryBcRowV1,
    shell: &LowBoostRecoveryCurriculumExportShellV1,
) -> Result<LowBoostRecoveryBcSerializedArtifactV1, LowBoostRecoveryBcSerializationExportError> {
    validate_low_boost_bc_contract_row(row)?;

    if !low_boost_bc_contract_shell_ready(shell) {
        return Err(
            LowBoostRecoveryBcSerializationExportError::AcceptedShellMalformed {
                detail: "shell no longer satisfies the accepted low-boost-recovery boundary",
            },
        );
    }

    if row.family != shell.family {
        return Err(
            LowBoostRecoveryBcSerializationExportError::RowShellInconsistent {
                detail: "family does not match accepted shell",
            },
        );
    }

    if row.source_slice_id != shell.source_slice_id {
        return Err(
            LowBoostRecoveryBcSerializationExportError::RowShellInconsistent {
                detail: "source_slice_id does not match accepted shell",
            },
        );
    }

    if row.source_replay != shell.source_replay {
        return Err(
            LowBoostRecoveryBcSerializationExportError::RowShellInconsistent {
                detail: "source_replay does not match accepted shell",
            },
        );
    }

    if row.source_subject != shell.source_subject {
        return Err(
            LowBoostRecoveryBcSerializationExportError::RowShellInconsistent {
                detail: "source_subject does not match accepted shell",
            },
        );
    }

    if row.source_raw_state_window_ref != shell.source_raw_state_window_ref {
        return Err(
            LowBoostRecoveryBcSerializationExportError::RowShellInconsistent {
                detail: "source_raw_state_window_ref does not match accepted shell",
            },
        );
    }

    if row.source_phase_id != shell.source_phase_id {
        return Err(
            LowBoostRecoveryBcSerializationExportError::RowShellInconsistent {
                detail: "source_phase_id does not match accepted shell",
            },
        );
    }

    if row.accepted_reference_variant_id != shell.accepted_reference_variant_id {
        return Err(
            LowBoostRecoveryBcSerializationExportError::RowShellInconsistent {
                detail: "accepted_reference_variant_id does not match accepted shell",
            },
        );
    }

    if row.carried_confidence_band != shell.confidence_band {
        return Err(
            LowBoostRecoveryBcSerializationExportError::RowShellInconsistent {
                detail: "carried_confidence_band does not match accepted shell",
            },
        );
    }

    if row.carried_unresolved_assumptions != shell.carried_unresolved_assumptions {
        return Err(
            LowBoostRecoveryBcSerializationExportError::RowShellInconsistent {
                detail: "carried_unresolved_assumptions do not match accepted shell",
            },
        );
    }

    let accepted_reference_window = shell.accepted_reference_variant_window.clone();
    let accepted_reference_variant_id = row.accepted_reference_variant_id.clone();

    Ok(LowBoostRecoveryBcSerializedArtifactV1 {
        artifact_id: LowBoostRecoveryBcArtifactId::new(format!(
            "{}:bc_artifact_v1",
            accepted_reference_variant_id.as_str()
        )),
        family: row.family.clone(),
        source_slice_id: row.source_slice_id.clone(),
        source_replay: row.source_replay.clone(),
        source_subject: row.source_subject.clone(),
        source_raw_state_window_ref: row.source_raw_state_window_ref.clone(),
        source_phase_id: row.source_phase_id,
        accepted_reference_variant_id: accepted_reference_variant_id.clone(),
        observation: LowBoostRecoveryBcObservationV1 {
            binding_kind: row.observation_binding_kind.clone(),
            supervision_window_role: row.supervision_window_role.clone(),
            accepted_reference_window: accepted_reference_window.clone(),
        },
        target: LowBoostRecoveryBcTargetV1 {
            binding_kind: row.target_binding_kind.clone(),
            accepted_reference_variant_id,
            accepted_reference_window,
        },
        carried_confidence_band: row.carried_confidence_band.clone(),
        carried_unresolved_assumptions: row.carried_unresolved_assumptions.clone(),
        artifact_notes: vec![
            LowBoostRecoveryBcArtifactNoteV1::SerializedFromBcContractRow,
            LowBoostRecoveryBcArtifactNoteV1::AcceptedShellReferenceWindowMaterialized,
            LowBoostRecoveryBcArtifactNoteV1::ObservationPayloadReferenceBound,
            LowBoostRecoveryBcArtifactNoteV1::TargetPayloadControlDeferred,
            LowBoostRecoveryBcArtifactNoteV1::ProvisionalConfidenceCarriedForward,
            LowBoostRecoveryBcArtifactNoteV1::UnresolvedAssumptionsCarriedForward,
            LowBoostRecoveryBcArtifactNoteV1::NotBcUsefulnessProof,
        ],
    })
}

pub fn handoff_persisted_low_boost_recovery_bc_artifact_v1(
    artifact: &PersistedLowBoostRecoveryBcArtifact,
) -> Result<LowBoostRecoveryBcArtifactConsumerHandoffV1, LowBoostRecoveryBcArtifactIntegrationError>
{
    let expected_schema = ArtifactKind::LowBoostRecoveryBcArtifact.schema();
    if artifact.header.schema_name != expected_schema.name {
        return Err(
            LowBoostRecoveryBcArtifactIntegrationError::ArtifactEnvelopeMalformed {
                detail: "header.schema_name must remain mimir.low_boost_recovery_bc_artifact",
            },
        );
    }

    if artifact.header.schema_version != expected_schema.version {
        return Err(
            LowBoostRecoveryBcArtifactIntegrationError::ArtifactEnvelopeMalformed {
                detail: "header.schema_version must remain 1 for mimir.low_boost_recovery_bc_artifact",
            },
        );
    }

    validate_low_boost_recovery_bc_serialized_artifact(&artifact.payload)?;

    Ok(LowBoostRecoveryBcArtifactConsumerHandoffV1 {
        artifact_id: artifact.payload.artifact_id.clone(),
        source_slice_id: artifact.payload.source_slice_id.clone(),
        source_replay: artifact.payload.source_replay.clone(),
        source_subject: artifact.payload.source_subject.clone(),
        source_raw_state_window_ref: artifact.payload.source_raw_state_window_ref.clone(),
        source_phase_id: artifact.payload.source_phase_id,
        accepted_reference_variant_id: artifact.payload.accepted_reference_variant_id.clone(),
        observation_binding_kind: artifact.payload.observation.binding_kind.clone(),
        supervision_window_role: artifact.payload.observation.supervision_window_role.clone(),
        accepted_reference_window: artifact
            .payload
            .observation
            .accepted_reference_window
            .clone(),
        target_binding_kind: artifact.payload.target.binding_kind.clone(),
        carried_confidence_band: artifact.payload.carried_confidence_band.clone(),
        carried_unresolved_assumptions: artifact.payload.carried_unresolved_assumptions.clone(),
    })
}

