pub fn batch_low_boost_recovery_bc_specimens_v1(
    refined_specimens: &[LowBoostRecoveryBcConsumerRefinementResultV1],
) -> Result<LowBoostRecoveryBcSpecimenBatchingResultV1, LowBoostRecoveryBcSpecimenBatchingError> {
    if refined_specimens.is_empty() {
        return Err(LowBoostRecoveryBcSpecimenBatchingError::NoSpecimensProvided);
    }

    let mut seen_artifact_ids = std::collections::BTreeSet::new();
    let mut ordered_specimens = Vec::with_capacity(refined_specimens.len());

    for (index, specimen) in refined_specimens.iter().enumerate() {
        validate_low_boost_recovery_bc_consumer_refinement_result_for_batching(specimen).map_err(
            |detail| LowBoostRecoveryBcSpecimenBatchingError::RefinedSpecimenMalformed {
                index,
                detail,
            },
        )?;

        if !seen_artifact_ids.insert(specimen.artifact_id.clone()) {
            return Err(
                LowBoostRecoveryBcSpecimenBatchingError::DuplicateArtifactId {
                    artifact_id: specimen.artifact_id.clone(),
                },
            );
        }

        ordered_specimens.push(specimen.clone());
    }

    ordered_specimens.sort_by(compare_low_boost_recovery_bc_specimens_for_batching);

    let specimen_count = ordered_specimens.len();
    let mut groups = Vec::new();

    for specimen in ordered_specimens {
        let starts_new_group =
            groups
                .last()
                .is_none_or(|group: &LowBoostRecoveryBcSpecimenBatchGroupV1| {
                    !low_boost_recovery_bc_batch_group_matches_specimen(group, &specimen)
                });

        if starts_new_group {
            groups.push(LowBoostRecoveryBcSpecimenBatchGroupV1 {
                group_ordinal: groups.len(),
                source_slice_id: specimen.source_slice_id.clone(),
                source_replay: specimen.source_replay.clone(),
                source_subject: specimen.source_subject.clone(),
                source_raw_state_window_ref: specimen.source_raw_state_window_ref.clone(),
                source_phase_id: specimen.source_phase_id,
                specimens: vec![specimen],
            });
        } else {
            groups
                .last_mut()
                .expect("group must exist when not starting a new group")
                .specimens
                .push(specimen);
        }
    }

    Ok(LowBoostRecoveryBcSpecimenBatchingResultV1 {
        specimen_count,
        groups,
        batching_disposition:
            LowBoostRecoveryBcSpecimenBatchingDispositionV1::ReadyForLowBoostRecoveryLayoutRefinementOnly,
    })
}

