pub fn emit_low_boost_recovery_bc_actual_filesystem_emission_v1(
    plan: &LowBoostRecoveryBcFilesystemExportEmissionPlanResultV1,
    output_parent_directory: impl AsRef<Path>,
) -> Result<
    LowBoostRecoveryBcActualFilesystemEmissionReceiptV1,
    LowBoostRecoveryBcActualFilesystemEmissionError,
> {
    validate_low_boost_recovery_bc_actual_filesystem_emission_plan_v1(plan)?;

    let output_parent_directory = output_parent_directory.as_ref();
    if !output_parent_directory.exists() {
        return Err(
            LowBoostRecoveryBcActualFilesystemEmissionError::OutputParentDirectoryInvalid {
                path: output_parent_directory.to_path_buf(),
                detail: "output parent directory must already exist",
            },
        );
    }

    if !output_parent_directory.is_dir() {
        return Err(
            LowBoostRecoveryBcActualFilesystemEmissionError::OutputParentDirectoryInvalid {
                path: output_parent_directory.to_path_buf(),
                detail: "output parent directory must be a directory",
            },
        );
    }

    let emitted_family_root_directory =
        output_parent_directory.join(&plan.planned_family_root_directory);
    if emitted_family_root_directory.exists() {
        return Err(
            LowBoostRecoveryBcActualFilesystemEmissionError::DestinationConflict {
                path: emitted_family_root_directory,
            },
        );
    }

    fs::create_dir(&emitted_family_root_directory).map_err(|error| {
        LowBoostRecoveryBcActualFilesystemEmissionError::WriteFailed {
            path: emitted_family_root_directory.clone(),
            detail: error.to_string(),
        }
    })?;

    let mut ordered_lane_receipts = Vec::with_capacity(plan.planned_recovery_context_lanes.len());

    for lane_plan in &plan.planned_recovery_context_lanes {
        let emitted_lane_directory =
            emitted_family_root_directory.join(&lane_plan.planned_relative_lane_directory);
        fs::create_dir(&emitted_lane_directory).map_err(|error| {
            cleanup_low_boost_recovery_bc_actual_filesystem_emission_failure(
                &emitted_family_root_directory,
                &emitted_lane_directory,
                error.to_string(),
            )
        })?;

        let mut ordered_specimen_receipts =
            Vec::with_capacity(lane_plan.ordered_specimen_plans.len());

        for (specimen_plan, specimen) in lane_plan
            .ordered_specimen_plans
            .iter()
            .zip(&lane_plan.preserved_lane.specimens)
        {
            let emitted_specimen_file_path = emitted_lane_directory.join(
                planned_low_boost_recovery_bc_actual_specimen_file_name(
                    &specimen_plan.planned_specimen_file_stem,
                ),
            );
            let emitted_specimen =
                build_low_boost_recovery_bc_actual_filesystem_emission_specimen_file_v1(
                    lane_plan.lane_ordinal,
                    specimen_plan.specimen_ordinal,
                    specimen,
                );

            mimir_io::write_low_boost_recovery_bc_actual_filesystem_emission_specimen_file_v1(
                &emitted_specimen_file_path,
                &emitted_specimen,
            )
            .map_err(|error| {
                cleanup_low_boost_recovery_bc_actual_filesystem_emission_failure(
                    &emitted_family_root_directory,
                    &emitted_specimen_file_path,
                    error.to_string(),
                )
            })?;

            ordered_specimen_receipts.push(
                LowBoostRecoveryBcActualFilesystemEmissionSpecimenReceiptV1 {
                    specimen_ordinal: specimen_plan.specimen_ordinal,
                    artifact_id: specimen_plan.artifact_id.clone(),
                    emitted_specimen_file_path,
                },
            );
        }

        ordered_lane_receipts.push(LowBoostRecoveryBcActualFilesystemEmissionLaneReceiptV1 {
            lane_ordinal: lane_plan.lane_ordinal,
            emitted_lane_directory,
            ordered_specimen_receipts,
        });
    }

    Ok(LowBoostRecoveryBcActualFilesystemEmissionReceiptV1 {
        emitted_family_root_directory,
        ordered_lane_receipts,
    })
}

pub fn audit_readback_low_boost_recovery_bc_emitted_output_v1(
    receipt: &LowBoostRecoveryBcActualFilesystemEmissionReceiptV1,
) -> Result<
    LowBoostRecoveryBcEmittedOutputAuditReadbackResultV1,
    LowBoostRecoveryBcEmittedOutputAuditReadbackError,
> {
    let (group_count, specimen_count) =
        validate_low_boost_recovery_bc_emitted_output_audit_readback_receipt_v1(receipt)?;

    if !receipt.emitted_family_root_directory.exists() {
        return Err(
            LowBoostRecoveryBcEmittedOutputAuditReadbackError::EmittedFamilyRootDirectoryInvalid {
                path: receipt.emitted_family_root_directory.clone(),
                detail: "emitted family root directory must exist",
            },
        );
    }

    if !receipt.emitted_family_root_directory.is_dir() {
        return Err(
            LowBoostRecoveryBcEmittedOutputAuditReadbackError::EmittedFamilyRootDirectoryInvalid {
                path: receipt.emitted_family_root_directory.clone(),
                detail: "emitted family root directory must be a directory",
            },
        );
    }

    let mut ordered_lane_results = Vec::with_capacity(receipt.ordered_lane_receipts.len());

    for (lane_index, lane_receipt) in receipt.ordered_lane_receipts.iter().enumerate() {
        if !lane_receipt.emitted_lane_directory.exists() {
            return Err(
                LowBoostRecoveryBcEmittedOutputAuditReadbackError::EmittedLaneDirectoryInvalid {
                    lane_index,
                    path: lane_receipt.emitted_lane_directory.clone(),
                    detail: "emitted lane directory must exist",
                },
            );
        }

        if !lane_receipt.emitted_lane_directory.is_dir() {
            return Err(
                LowBoostRecoveryBcEmittedOutputAuditReadbackError::EmittedLaneDirectoryInvalid {
                    lane_index,
                    path: lane_receipt.emitted_lane_directory.clone(),
                    detail: "emitted lane directory must be a directory",
                },
            );
        }

        let mut ordered_specimen_results =
            Vec::with_capacity(lane_receipt.ordered_specimen_receipts.len());

        for (specimen_index, specimen_receipt) in
            lane_receipt.ordered_specimen_receipts.iter().enumerate()
        {
            if !specimen_receipt.emitted_specimen_file_path.exists() {
                return Err(
                    LowBoostRecoveryBcEmittedOutputAuditReadbackError::EmittedSpecimenFileInvalid {
                        lane_index,
                        specimen_index,
                        path: specimen_receipt.emitted_specimen_file_path.clone(),
                        detail: "emitted specimen file must exist",
                    },
                );
            }

            if !specimen_receipt.emitted_specimen_file_path.is_file() {
                return Err(
                    LowBoostRecoveryBcEmittedOutputAuditReadbackError::EmittedSpecimenFileInvalid {
                        lane_index,
                        specimen_index,
                        path: specimen_receipt.emitted_specimen_file_path.clone(),
                        detail: "emitted specimen path must be a file",
                    },
                );
            }

            let readback_specimen =
                mimir_io::read_low_boost_recovery_bc_actual_filesystem_emission_specimen_file_v1(
                    &specimen_receipt.emitted_specimen_file_path,
                )
                .map_err(|error| {
                    LowBoostRecoveryBcEmittedOutputAuditReadbackError::SpecimenReadbackFailed {
                        lane_index,
                        specimen_index,
                        path: specimen_receipt.emitted_specimen_file_path.clone(),
                        detail: error.to_string(),
                    }
                })?;

            validate_low_boost_recovery_bc_actual_filesystem_emission_specimen_file_for_audit(
                &readback_specimen,
            )
            .map_err(|detail| {
                LowBoostRecoveryBcEmittedOutputAuditReadbackError::SpecimenReadbackInvalid {
                    lane_index,
                    specimen_index,
                    detail,
                }
            })?;

            if readback_specimen.lane_ordinal != lane_receipt.lane_ordinal {
                return Err(
                    LowBoostRecoveryBcEmittedOutputAuditReadbackError::SpecimenReadbackMismatch {
                        lane_index,
                        specimen_index,
                        detail: "lane_ordinal must match the enclosing lane receipt",
                    },
                );
            }

            if readback_specimen.specimen_ordinal != specimen_receipt.specimen_ordinal {
                return Err(
                    LowBoostRecoveryBcEmittedOutputAuditReadbackError::SpecimenReadbackMismatch {
                        lane_index,
                        specimen_index,
                        detail: "specimen_ordinal must match the specimen receipt",
                    },
                );
            }

            if readback_specimen.artifact_id != specimen_receipt.artifact_id {
                return Err(
                    LowBoostRecoveryBcEmittedOutputAuditReadbackError::SpecimenReadbackMismatch {
                        lane_index,
                        specimen_index,
                        detail: "artifact_id must match the specimen receipt",
                    },
                );
            }

            ordered_specimen_results.push(
                LowBoostRecoveryBcEmittedOutputAuditReadbackSpecimenResultV1 {
                    specimen_ordinal: specimen_receipt.specimen_ordinal,
                    artifact_id: specimen_receipt.artifact_id.clone(),
                    emitted_specimen_file_path: specimen_receipt.emitted_specimen_file_path.clone(),
                    specimen_file_exists: true,
                    readback_matches_receipt_contract: true,
                    readback_specimen,
                },
            );
        }

        ordered_lane_results.push(LowBoostRecoveryBcEmittedOutputAuditReadbackLaneResultV1 {
            lane_ordinal: lane_receipt.lane_ordinal,
            emitted_lane_directory: lane_receipt.emitted_lane_directory.clone(),
            lane_directory_exists: true,
            ordered_specimen_results,
        });
    }

    Ok(LowBoostRecoveryBcEmittedOutputAuditReadbackResultV1 {
        specimen_count,
        group_count,
        emitted_family_root_directory: receipt.emitted_family_root_directory.clone(),
        family_root_directory_exists: true,
        ordered_lane_results,
        audit_disposition:
            LowBoostRecoveryBcEmittedOutputAuditReadbackDispositionV1::ReadyForLowBoostRecoveryEmittedOutputRefinementOnly,
        audit_notes: vec![
            LowBoostRecoveryBcEmittedOutputAuditReadbackNoteV1::ActualFilesystemEmissionReceiptBoundaryPreserved,
            LowBoostRecoveryBcEmittedOutputAuditReadbackNoteV1::EmittedRootLaneSpecimenPathsVerified,
            LowBoostRecoveryBcEmittedOutputAuditReadbackNoteV1::FamilySpecificSpecimenReadbackVerified,
            LowBoostRecoveryBcEmittedOutputAuditReadbackNoteV1::NoAdditionalSemanticsInferredBeyondEmittedContract,
            LowBoostRecoveryBcEmittedOutputAuditReadbackNoteV1::TensorAndControlMaterializationDeferred,
            LowBoostRecoveryBcEmittedOutputAuditReadbackNoteV1::MimirExportIntegrationDeferred,
        ],
    })
}

