pub fn validate_low_boost_recovery_bc_receipt_bound_specimen_file_existence_readback_v1(
    realization: &LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationResultV1,
) -> Result<
    LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationResultV1,
    LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationError,
> {
    validate_low_boost_recovery_bc_receipt_bound_specimen_file_locator_realization_result_for_existence_readback_validation(
        realization,
    )?;

    let mut preserved_ordered_lane_results =
        Vec::with_capacity(realization.preserved_ordered_lane_results.len());

    for (lane_index, lane) in realization
        .preserved_ordered_lane_results
        .iter()
        .enumerate()
    {
        let mut ordered_specimen_results = Vec::with_capacity(lane.ordered_specimen_results.len());

        for (specimen_index, specimen) in lane.ordered_specimen_results.iter().enumerate() {
            let realized_locator = &specimen.realized_locator;

            if !realized_locator.anchored_bc_specimen_file_path.exists() {
                return Err(
                    LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationError::SpecimenFileMissing {
                        lane_index,
                        specimen_index,
                        path: realized_locator.anchored_bc_specimen_file_path.clone(),
                    },
                );
            }

            if !realized_locator.anchored_bc_specimen_file_path.is_file() {
                return Err(
                    LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationError::SpecimenFileInvalid {
                        lane_index,
                        specimen_index,
                        path: realized_locator.anchored_bc_specimen_file_path.clone(),
                        detail: "anchored_bc_specimen_file_path must be a file",
                    },
                );
            }

            let readback_specimen =
                mimir_io::read_low_boost_recovery_bc_actual_filesystem_emission_specimen_file_v1(
                    &realized_locator.anchored_bc_specimen_file_path,
                )
                .map_err(|error| {
                    LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationError::SpecimenReadbackFailed {
                        lane_index,
                        specimen_index,
                        path: realized_locator.anchored_bc_specimen_file_path.clone(),
                        detail: error.to_string(),
                    }
                })?;

            validate_low_boost_recovery_bc_actual_filesystem_emission_specimen_file_for_audit(
                &readback_specimen,
            )
            .map_err(|detail| {
                LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationError::SpecimenReadbackInvalid {
                    lane_index,
                    specimen_index,
                    detail,
                }
            })?;

            if readback_specimen.lane_ordinal != realized_locator.lane_ordinal {
                return Err(
                    LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationError::SpecimenReadbackMismatch {
                        lane_index,
                        specimen_index,
                        detail: "readback lane_ordinal must match realized locator lane_ordinal",
                    },
                );
            }

            if readback_specimen.specimen_ordinal != realized_locator.specimen_ordinal {
                return Err(
                    LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationError::SpecimenReadbackMismatch {
                        lane_index,
                        specimen_index,
                        detail: "readback specimen_ordinal must match realized locator specimen_ordinal",
                    },
                );
            }

            if readback_specimen.artifact_id != realized_locator.artifact_id {
                return Err(
                    LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationError::SpecimenReadbackMismatch {
                        lane_index,
                        specimen_index,
                        detail: "readback artifact_id must match realized locator artifact_id",
                    },
                );
            }

            if readback_specimen.source_raw_state_window_ref
                != realized_locator.source_raw_state_window_ref
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationError::SpecimenReadbackMismatch {
                        lane_index,
                        specimen_index,
                        detail: "readback source_raw_state_window_ref must match realized locator source_raw_state_window_ref",
                    },
                );
            }

            ordered_specimen_results.push(
                LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationSpecimenResultV1 {
                    specimen_ordinal: specimen.specimen_ordinal,
                    preserved_realized_locator: realized_locator.clone(),
                    specimen_file_exists: true,
                    readback_matches_realized_locator_identity: true,
                    readback_specimen,
                },
            );
        }

        preserved_ordered_lane_results.push(
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationLaneResultV1 {
                lane_ordinal: lane.lane_ordinal,
                ordered_specimen_results,
            },
        );
    }

    Ok(LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationResultV1 {
        specimen_count: realization.specimen_count,
        group_count: realization.group_count,
        source_realization_disposition: realization.realization_disposition,
        source_realization_notes: realization.realization_notes.clone(),
        source_chosen_locator_contract_shape: realization.source_chosen_locator_contract_shape,
        audited_family_root_directory: realization.audited_family_root_directory.clone(),
        preserved_ordered_lane_results,
        validation_disposition:
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationDispositionV1::ValidatedForReceiptBoundBcSpecimenFileExistenceAndIdentityPreservingReadbackOnly,
        validation_notes: vec![
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::ReceiptBoundSpecimenFileAnchoredLocatorRealizationBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::AuditedFamilyRootReferencePreservedAsBcSpecimenTreeAnchor,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::LaneAndSpecimenOrderPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::ArtifactIdsPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::SourceRawStateWindowRefsPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::DeterministicRelativeSpecimenFilePathShapeRevalidated,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::AnchoredBcSpecimenFileExistenceVerified,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::FamilySpecificSpecimenFileReadbackValidated,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::ReadbackIdentityAlignedWithRealizedLocator,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::RawStateMaterializationDeferred,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::SidecarManifestAndGenericIndexStillUnjustified,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::MimirExportIntegrationStillForbidden,
        ],
    })
}

