fn validate_low_boost_recovery_bc_receipt_bound_validated_specimen_file_raw_state_window_replay_input_access_source_binding_realization_result_for_replay_input_locator_reopen_decision(
    realization: &LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationResultV1,
) -> Result<(), LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError> {
    if realization.source_contract_disposition
        != LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractDispositionV1::ContractDefinedForReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "source_contract_disposition must remain contract_defined_for_receipt_bound_validated_specimen_file_raw_state_window_replay_input_access_source_binding_only",
            },
        );
    }

    if !matches_exactly_once(
        &realization.source_contract_notes,
        &[
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::ReplaySideParseAttemptRealizationBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::ReplayInputAccessReopenDecisionBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::RealizationAndReopenInputsCrossValidated,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::AuditedFamilyRootReferencePreservedAsBcSpecimenTreeAnchor,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::LaneAndSpecimenOrderPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::ArtifactIdsPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::AnchoredBcSpecimenFilePathsPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::SourceRawStateWindowRefsPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::ReceiptBoundSourceLineagePreservedForReplayInputAccessSourceBindingOnly,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::ObservationBindingKindAndAcceptedReferenceWindowPreservedForDeferredObservationAccess,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::SourceReplayReferenceRemainsOpaqueLineageOnly,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::ReplayInputAccessSourceBindingContractOnlyBoundaryDefined,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::FutureParserConsumableReplayHandleContractOnlyOutputBoundaryDefined,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::ReplayInputLocatorImplementationStillDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::ReplayParsingStillDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::ActualRawStatePayloadMaterializationDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::TensorAndControlMaterializationStillDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::SidecarManifestAndGenericIndexStillUnjustified,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingContractNoteV1::MimirExportIntegrationStillForbidden,
        ],
    ) {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "source_contract_notes must remain the exact low-boost-recovery replay-input-access source-binding contract note set",
            },
        );
    }

    if realization.source_chosen_locator_contract_shape
        != LowBoostRecoveryBcReceiptBoundRawStateWindowLocatorContractShapeV1::ReceiptBoundSpecimenFileAnchored
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "source_chosen_locator_contract_shape must remain receipt_bound_specimen_file_anchored",
            },
        );
    }

    if realization.source_chosen_materialization_contract_shape
        != LowBoostRecoveryBcRawStateMaterializationContractShapeV1::ReceiptBoundValidatedSpecimenFileSourceRawStateWindowRefMaterializationAttemptOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "source_chosen_materialization_contract_shape must remain receipt_bound_validated_specimen_file_source_raw_state_window_ref_materialization_attempt_only",
            },
        );
    }

    if realization.source_chosen_replay_parsing_contract_shape
        != LowBoostRecoveryBcReplayParsingContractShapeV1::ReceiptBoundValidatedSpecimenFileSourceRawStateWindowRefReplaySideParseAttemptOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "source_chosen_replay_parsing_contract_shape must remain receipt_bound_validated_specimen_file_source_raw_state_window_ref_replay_side_parse_attempt_only",
            },
        );
    }

    if realization.realization_disposition
        != LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationDispositionV1::RealizedForTruthfulNonLocatedReplayInputAccessSourceBindingOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "realization_disposition must remain realized_for_truthful_non_located_replay_input_access_source_binding_only",
            },
        );
    }

    if !matches_exactly_once(
        &realization.realization_notes,
        &[
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ReplayInputAccessSourceBindingContractBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ContractInputsRevalidated,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::AuditedFamilyRootReferencePreservedAsBcSpecimenTreeAnchor,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::LaneAndSpecimenOrderPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ArtifactIdsPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::AnchoredBcSpecimenFilePathsPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::SourceRawStateWindowRefsPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ReceiptBoundSourceLineagePreservedForNonLocatedReplayInputAccessSourceBindingOnly,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ObservationBindingKindAndAcceptedReferenceWindowPreservedForDeferredObservationAccess,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::SourceReplayReferenceRemainsOpaqueLineageOnly,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::FutureParserConsumableReplayHandleKindPreservedWithoutLocatorRealization,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::TruthfulNonLocatedReplayInputAccessSourceBindingResultOnly,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ReplayInputLocatorImplementationStillDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ReplayParsingStillDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ActualRawStatePayloadMaterializationDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::TensorAndControlMaterializationStillDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::SidecarManifestAndGenericIndexStillUnjustified,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::MimirExportIntegrationStillForbidden,
        ],
    ) {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "realization_notes must remain the exact low-boost-recovery replay-input-access source-binding realization note set",
            },
        );
    }

    if realization.chosen_replay_input_access_contract_shape
        != LowBoostRecoveryBcReceiptBoundReplayInputAccessContractShapeV1::ReceiptBoundReplayInputAccessSourceBindingOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "chosen_replay_input_access_contract_shape must remain receipt_bound_replay_input_access_source_binding_only",
            },
        );
    }

    if realization.specimen_count == 0 {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "specimen_count must remain greater than zero",
            },
        );
    }

    if realization.group_count == 0 {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "group_count must remain greater than zero",
            },
        );
    }

    if realization
        .audited_family_root_directory
        .file_name()
        .and_then(|name| name.to_str())
        != Some(LOW_BOOST_RECOVERY_BC_FILESYSTEM_EXPORT_EMISSION_ROOT_DIRECTORY_V1)
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "audited_family_root_directory must remain low_boost_recovery_bc_v1",
            },
        );
    }

    if !realization.audited_family_root_directory.exists() {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "audited_family_root_directory must exist for replay-input locator reopen decision",
            },
        );
    }

    if !realization.audited_family_root_directory.is_dir() {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "audited_family_root_directory must be a directory for replay-input locator reopen decision",
            },
        );
    }

    if realization.group_count != realization.preserved_ordered_lane_results.len() {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "group_count must equal the number of preserved ordered lane results",
            },
        );
    }

    let mut total_specimens = 0usize;
    let mut seen_artifact_ids = HashSet::new();

    for (lane_index, lane) in realization
        .preserved_ordered_lane_results
        .iter()
        .enumerate()
    {
        if lane.lane_ordinal != lane_index {
            return Err(
                LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::LaneResultMalformed {
                    lane_index,
                    detail: "lane_ordinal must match lane position",
                },
            );
        }

        if lane.ordered_specimen_results.is_empty() {
            return Err(
                LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::LaneResultMalformed {
                    lane_index,
                    detail: "ordered_specimen_results must not be empty",
                },
            );
        }

        for (specimen_index, specimen) in lane.ordered_specimen_results.iter().enumerate() {
            if specimen.specimen_ordinal != specimen_index {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "specimen_ordinal must match specimen position",
                    },
                );
            }

            let boundary_input =
                &specimen.consumed_replay_input_access_source_binding_boundary_input;
            let output_boundary =
                &specimen.preserved_replay_input_access_source_binding_output_boundary;

            if boundary_input.anchored_bc_specimen_file_path
                == realization.audited_family_root_directory
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "consumed_replay_input_access_source_binding_boundary_input anchored_bc_specimen_file_path must remain a specimen file path below audited_family_root_directory",
                    },
                );
            }

            if !boundary_input
                .anchored_bc_specimen_file_path
                .starts_with(&realization.audited_family_root_directory)
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "consumed_replay_input_access_source_binding_boundary_input anchored_bc_specimen_file_path must remain receipt-bound below audited_family_root_directory",
                    },
                );
            }

            if boundary_input.lane_ordinal != lane.lane_ordinal {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "consumed_replay_input_access_source_binding_boundary_input lane_ordinal must match enclosing lane_ordinal",
                    },
                );
            }

            if boundary_input.specimen_ordinal != specimen.specimen_ordinal {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "consumed_replay_input_access_source_binding_boundary_input specimen_ordinal must match specimen_ordinal",
                    },
                );
            }

            if boundary_input
                .preserved_observation_binding_kind
                != LowBoostRecoveryBcObservationBindingKindV1::AcceptedReferenceWindowFromRawStateWindowRef
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "consumed_replay_input_access_source_binding_boundary_input preserved_observation_binding_kind must remain accepted_reference_window_from_raw_state_window_ref",
                    },
                );
            }

            if !valid_time_window(&boundary_input.preserved_accepted_reference_window) {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "consumed_replay_input_access_source_binding_boundary_input preserved_accepted_reference_window must remain a valid bounded window",
                    },
                );
            }

            if output_boundary.lane_ordinal != lane.lane_ordinal {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved_replay_input_access_source_binding_output_boundary lane_ordinal must match enclosing lane_ordinal",
                    },
                );
            }

            if output_boundary.specimen_ordinal != specimen.specimen_ordinal {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved_replay_input_access_source_binding_output_boundary specimen_ordinal must match specimen_ordinal",
                    },
                );
            }

            if output_boundary.artifact_id != boundary_input.artifact_id {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved_replay_input_access_source_binding_output_boundary artifact_id must match consumed_replay_input_access_source_binding_boundary_input artifact_id",
                    },
                );
            }

            if output_boundary.anchored_bc_specimen_file_path
                != boundary_input.anchored_bc_specimen_file_path
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved_replay_input_access_source_binding_output_boundary anchored_bc_specimen_file_path must match consumed_replay_input_access_source_binding_boundary_input anchored_bc_specimen_file_path",
                    },
                );
            }

            if output_boundary.source_raw_state_window_ref
                != boundary_input.source_raw_state_window_ref
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved_replay_input_access_source_binding_output_boundary source_raw_state_window_ref must match consumed_replay_input_access_source_binding_boundary_input source_raw_state_window_ref",
                    },
                );
            }

            if output_boundary.source_slice_id != boundary_input.source_slice_id {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved_replay_input_access_source_binding_output_boundary source_slice_id must match consumed_replay_input_access_source_binding_boundary_input source_slice_id",
                    },
                );
            }

            if output_boundary.source_replay != boundary_input.source_replay {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved_replay_input_access_source_binding_output_boundary source_replay must match consumed_replay_input_access_source_binding_boundary_input source_replay",
                    },
                );
            }

            if output_boundary.source_subject != boundary_input.source_subject {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved_replay_input_access_source_binding_output_boundary source_subject must match consumed_replay_input_access_source_binding_boundary_input source_subject",
                    },
                );
            }

            if output_boundary.source_phase_id != boundary_input.source_phase_id {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved_replay_input_access_source_binding_output_boundary source_phase_id must match consumed_replay_input_access_source_binding_boundary_input source_phase_id",
                    },
                );
            }

            if output_boundary.preserved_observation_binding_kind
                != boundary_input.preserved_observation_binding_kind
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved_replay_input_access_source_binding_output_boundary preserved_observation_binding_kind must match consumed_replay_input_access_source_binding_boundary_input preserved_observation_binding_kind",
                    },
                );
            }

            if output_boundary.preserved_accepted_reference_window
                != boundary_input.preserved_accepted_reference_window
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved_replay_input_access_source_binding_output_boundary preserved_accepted_reference_window must match consumed_replay_input_access_source_binding_boundary_input preserved_accepted_reference_window",
                    },
                );
            }

            if !valid_time_window(&output_boundary.preserved_accepted_reference_window) {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved_replay_input_access_source_binding_output_boundary preserved_accepted_reference_window must remain a valid bounded window",
                    },
                );
            }

            if output_boundary.bound_replay_input_access_source_binding_handle_kind
                != LowBoostRecoveryBcReceiptBoundReplayInputAccessSourceBindingHandleKindV1::FutureParserConsumableReplayHandleOnly
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved_replay_input_access_source_binding_output_boundary bound_replay_input_access_source_binding_handle_kind must remain future_parser_consumable_replay_handle_only",
                    },
                );
            }

            if specimen.replay_input_access_source_binding_disposition
                != LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationDispositionV1::RealizedForTruthfulNonLocatedReplayInputAccessSourceBindingOnly
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "replay_input_access_source_binding_disposition must remain realized_for_truthful_non_located_replay_input_access_source_binding_only",
                    },
                );
            }

            if !seen_artifact_ids.insert(boundary_input.artifact_id.clone()) {
                return Err(
                    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                        detail: "artifact_id values must remain unique across preserved ordered lane results",
                    },
                );
            }

            total_specimens += 1;
        }
    }

    if total_specimens != realization.specimen_count {
        return Err(
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError::RealizationResultMalformed {
                detail: "specimen_count must equal the number of preserved ordered specimen results",
            },
        );
    }

    Ok(())
}

pub fn decide_low_boost_recovery_bc_receipt_bound_replay_input_locator_reopen_from_receipt_bound_validated_specimen_file_raw_state_window_replay_input_access_source_binding_realization_v1(
    realization: &LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationResultV1,
) -> Result<
    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionResultV1,
    LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionError,
> {
    validate_low_boost_recovery_bc_receipt_bound_validated_specimen_file_raw_state_window_replay_input_access_source_binding_realization_result_for_replay_input_locator_reopen_decision(
        realization,
    )?;

    Ok(LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionResultV1 {
        specimen_count: realization.specimen_count,
        group_count: realization.group_count,
        source_realization_disposition: realization.realization_disposition,
        source_realization_notes: realization.realization_notes.clone(),
        source_chosen_locator_contract_shape: realization.source_chosen_locator_contract_shape,
        source_chosen_materialization_contract_shape: realization
            .source_chosen_materialization_contract_shape,
        source_chosen_replay_parsing_contract_shape: realization
            .source_chosen_replay_parsing_contract_shape,
        source_chosen_replay_input_access_contract_shape: realization
            .chosen_replay_input_access_contract_shape,
        audited_family_root_directory: realization.audited_family_root_directory.clone(),
        decision_disposition:
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDispositionV1::ReopenJustifiedForReceiptBoundReplayInputLocatorContract,
        decision_notes: vec![
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::ReplayInputAccessSourceBindingRealizationBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::RealizationInputRevalidated,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::AuditedFamilyRootReferencePreservedAsBcSpecimenTreeAnchor,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::TruthfulNonLocatedReplayInputAccessSourceBindingBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::AnchoredBcSpecimenFilePathsPreserved,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::SourceRawStateWindowRefsPreserved,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::ReceiptBoundSourceReplayLineagePreserved,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::ObservationBindingKindAndAcceptedReferenceWindowPreservedForDeferredObservationAccess,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::SourceReplayReferenceRemainsOpaqueLineagePendingReplayInputLocatorContract,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::FutureParserConsumableReplayHandleRemainsContractOnlyPendingReplayInputLocatorBoundary,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::MissingPieceIsReceiptBoundReplayInputLocatorOnly,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::ReceiptBoundReplayInputLocatorContractIsMinimumHonestReopen,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::ReplayInputLocatorImplementationStillDeferredInDecisionPass,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::ReplayParsingImplementationStillDeferredInDecisionPass,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::ActualRawStatePayloadMaterializationDeferred,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::TensorAndControlMaterializationStillDeferred,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::SidecarManifestAndGenericIndexStillUnjustified,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::MimirExportIntegrationStillForbidden,
        ],
        chosen_replay_input_locator_contract_shape:
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorContractShapeV1::ReceiptBoundReplayInputLocatorOnly,
    })
}

fn validate_low_boost_recovery_bc_replay_input_locator_reopen_decision_result_for_receipt_bound_validated_specimen_file_raw_state_window_replay_input_locator_contract_definition(
    reopen: &LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionResultV1,
) -> Result<
    (),
    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError,
>{
    if reopen.source_realization_disposition
        != LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationDispositionV1::RealizedForTruthfulNonLocatedReplayInputAccessSourceBindingOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "source_realization_disposition must remain realized_for_truthful_non_located_replay_input_access_source_binding_only",
            },
        );
    }

    if !matches_exactly_once(
        &reopen.source_realization_notes,
        &[
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ReplayInputAccessSourceBindingContractBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ContractInputsRevalidated,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::AuditedFamilyRootReferencePreservedAsBcSpecimenTreeAnchor,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::LaneAndSpecimenOrderPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ArtifactIdsPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::AnchoredBcSpecimenFilePathsPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::SourceRawStateWindowRefsPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ReceiptBoundSourceLineagePreservedForNonLocatedReplayInputAccessSourceBindingOnly,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ObservationBindingKindAndAcceptedReferenceWindowPreservedForDeferredObservationAccess,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::SourceReplayReferenceRemainsOpaqueLineageOnly,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::FutureParserConsumableReplayHandleKindPreservedWithoutLocatorRealization,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::TruthfulNonLocatedReplayInputAccessSourceBindingResultOnly,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ReplayInputLocatorImplementationStillDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ReplayParsingStillDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::ActualRawStatePayloadMaterializationDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::TensorAndControlMaterializationStillDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::SidecarManifestAndGenericIndexStillUnjustified,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationNoteV1::MimirExportIntegrationStillForbidden,
        ],
    ) {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "source_realization_notes must remain the exact low-boost-recovery replay-input-access source-binding realization note set",
            },
        );
    }

    if reopen.source_chosen_locator_contract_shape
        != LowBoostRecoveryBcReceiptBoundRawStateWindowLocatorContractShapeV1::ReceiptBoundSpecimenFileAnchored
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "source_chosen_locator_contract_shape must remain receipt_bound_specimen_file_anchored",
            },
        );
    }

    if reopen.source_chosen_materialization_contract_shape
        != LowBoostRecoveryBcRawStateMaterializationContractShapeV1::ReceiptBoundValidatedSpecimenFileSourceRawStateWindowRefMaterializationAttemptOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "source_chosen_materialization_contract_shape must remain receipt_bound_validated_specimen_file_source_raw_state_window_ref_materialization_attempt_only",
            },
        );
    }

    if reopen.source_chosen_replay_parsing_contract_shape
        != LowBoostRecoveryBcReplayParsingContractShapeV1::ReceiptBoundValidatedSpecimenFileSourceRawStateWindowRefReplaySideParseAttemptOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "source_chosen_replay_parsing_contract_shape must remain receipt_bound_validated_specimen_file_source_raw_state_window_ref_replay_side_parse_attempt_only",
            },
        );
    }

    if reopen.source_chosen_replay_input_access_contract_shape
        != LowBoostRecoveryBcReceiptBoundReplayInputAccessContractShapeV1::ReceiptBoundReplayInputAccessSourceBindingOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "source_chosen_replay_input_access_contract_shape must remain receipt_bound_replay_input_access_source_binding_only",
            },
        );
    }

    if reopen.decision_disposition
        != LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDispositionV1::ReopenJustifiedForReceiptBoundReplayInputLocatorContract
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "decision_disposition must remain reopen_justified_for_receipt_bound_replay_input_locator_contract",
            },
        );
    }

    if !matches_exactly_once(
        &reopen.decision_notes,
        &[
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::ReplayInputAccessSourceBindingRealizationBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::RealizationInputRevalidated,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::AuditedFamilyRootReferencePreservedAsBcSpecimenTreeAnchor,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::TruthfulNonLocatedReplayInputAccessSourceBindingBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::AnchoredBcSpecimenFilePathsPreserved,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::SourceRawStateWindowRefsPreserved,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::ReceiptBoundSourceReplayLineagePreserved,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::ObservationBindingKindAndAcceptedReferenceWindowPreservedForDeferredObservationAccess,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::SourceReplayReferenceRemainsOpaqueLineagePendingReplayInputLocatorContract,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::FutureParserConsumableReplayHandleRemainsContractOnlyPendingReplayInputLocatorBoundary,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::MissingPieceIsReceiptBoundReplayInputLocatorOnly,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::ReceiptBoundReplayInputLocatorContractIsMinimumHonestReopen,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::ReplayInputLocatorImplementationStillDeferredInDecisionPass,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::ReplayParsingImplementationStillDeferredInDecisionPass,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::ActualRawStatePayloadMaterializationDeferred,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::TensorAndControlMaterializationStillDeferred,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::SidecarManifestAndGenericIndexStillUnjustified,
            LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenNoteV1::MimirExportIntegrationStillForbidden,
        ],
    ) {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "decision_notes must remain the exact low-boost-recovery replay-input locator reopen decision note set",
            },
        );
    }

    if reopen.specimen_count == 0 {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "specimen_count must remain greater than zero",
            },
        );
    }

    if reopen.group_count == 0 {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "group_count must remain greater than zero",
            },
        );
    }

    if reopen
        .audited_family_root_directory
        .file_name()
        .and_then(|name| name.to_str())
        != Some(LOW_BOOST_RECOVERY_BC_FILESYSTEM_EXPORT_EMISSION_ROOT_DIRECTORY_V1)
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "audited_family_root_directory must remain low_boost_recovery_bc_v1",
            },
        );
    }

    if !reopen.audited_family_root_directory.exists() {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "audited_family_root_directory must exist for replay-input locator contract definition",
            },
        );
    }

    if !reopen.audited_family_root_directory.is_dir() {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "audited_family_root_directory must be a directory for replay-input locator contract definition",
            },
        );
    }

    if reopen.chosen_replay_input_locator_contract_shape
        != LowBoostRecoveryBcReceiptBoundReplayInputLocatorContractShapeV1::ReceiptBoundReplayInputLocatorOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "chosen_replay_input_locator_contract_shape must remain receipt_bound_replay_input_locator_only",
            },
        );
    }

    Ok(())
}

fn validate_low_boost_recovery_bc_replay_input_access_source_binding_realization_and_replay_input_locator_reopen_for_receipt_bound_validated_specimen_file_raw_state_window_replay_input_locator_contract_definition(
    realization: &LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputAccessSourceBindingRealizationResultV1,
    reopen: &LowBoostRecoveryBcReceiptBoundReplayInputLocatorReopenDecisionResultV1,
) -> Result<
    (),
    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError,
>{
    validate_low_boost_recovery_bc_receipt_bound_validated_specimen_file_raw_state_window_replay_input_access_source_binding_realization_result_for_replay_input_locator_reopen_decision(
        realization,
    )
    .map_err(|source| {
        LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::RealizationInputRejected {
            source,
        }
    })?;
    validate_low_boost_recovery_bc_replay_input_locator_reopen_decision_result_for_receipt_bound_validated_specimen_file_raw_state_window_replay_input_locator_contract_definition(
        reopen,
    )?;

    if realization.specimen_count != reopen.specimen_count {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::InputMismatch {
                detail: "reopen specimen_count must match realization specimen_count",
            },
        );
    }

    if realization.group_count != reopen.group_count {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::InputMismatch {
                detail: "reopen group_count must match realization group_count",
            },
        );
    }

    if realization.realization_disposition != reopen.source_realization_disposition {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::InputMismatch {
                detail: "reopen source_realization_disposition must match realization_disposition",
            },
        );
    }

    if realization.realization_notes != reopen.source_realization_notes {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::InputMismatch {
                detail: "reopen source_realization_notes must match realization_notes",
            },
        );
    }

    if realization.source_chosen_locator_contract_shape
        != reopen.source_chosen_locator_contract_shape
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::InputMismatch {
                detail: "reopen source_chosen_locator_contract_shape must match realization source_chosen_locator_contract_shape",
            },
        );
    }

    if realization.source_chosen_materialization_contract_shape
        != reopen.source_chosen_materialization_contract_shape
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::InputMismatch {
                detail: "reopen source_chosen_materialization_contract_shape must match realization source_chosen_materialization_contract_shape",
            },
        );
    }

    if realization.source_chosen_replay_parsing_contract_shape
        != reopen.source_chosen_replay_parsing_contract_shape
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::InputMismatch {
                detail: "reopen source_chosen_replay_parsing_contract_shape must match realization source_chosen_replay_parsing_contract_shape",
            },
        );
    }

    if realization.chosen_replay_input_access_contract_shape
        != reopen.source_chosen_replay_input_access_contract_shape
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::InputMismatch {
                detail: "reopen source_chosen_replay_input_access_contract_shape must match realization chosen_replay_input_access_contract_shape",
            },
        );
    }

    if realization.audited_family_root_directory != reopen.audited_family_root_directory {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplayInputLocatorContractDefinitionError::InputMismatch {
                detail: "reopen audited_family_root_directory must match realization audited_family_root_directory",
            },
        );
    }

    Ok(())
}

