                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationByteBackedCallerAdmittedSourceFormContractDefinitionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "admitted_replay_source_actual_materialization_explicit_carrier_provenance_source_binding_admission_boundary_input anchored_bc_specimen_file_path must remain receipt-bound below audited_family_root_directory",
                    },
                );
