            if !valid_time_window(&admission_input.preserved_accepted_reference_window) {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationByteBackedCallerAdmittedSourceFormContractDefinitionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "admitted_replay_source_actual_materialization_explicit_carrier_provenance_source_binding_admission_boundary_input preserved_accepted_reference_window must remain a valid bounded window",
                    },
                );
            }

