fn validate_low_boost_recovery_bc_receipt_bound_validated_specimen_file_raw_state_window_replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_contract_for_realization(
    contract: &LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeContractV1,
) -> Result<
    (),
    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError,
>{
    let opaque_handoff_view =
        low_boost_recovery_bc_receipt_bound_validated_specimen_file_raw_state_window_replay_source_actual_materialization_opaque_handoff_realization_view_from_consumer_intake_contract_v1(
            contract,
        );
    validate_low_boost_recovery_bc_receipt_bound_validated_specimen_file_raw_state_window_replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_realization_result_for_consumer_intake_contract_definition(
        &opaque_handoff_view,
    )
    .map_err(
        map_low_boost_recovery_bc_opaque_handoff_consumer_intake_contract_definition_error_to_realization_error,
    )?;

    if contract.contract_disposition
        != LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeContractDispositionV1::ContractDefinedForReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::ContractResultMalformed {
                detail: "contract_disposition must remain contract_defined_for_receipt_bound_validated_specimen_file_raw_state_window_replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_only",
            },
        );
    }

    if !matches_exactly_once(
        &contract.contract_notes,
        &low_boost_recovery_bc_receipt_bound_validated_specimen_file_raw_state_window_replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_contract_notes_v1(),
    ) {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::ContractResultMalformed {
                detail: "contract_notes must remain the exact low-boost-recovery opaque caller-admitted replay-byte handoff consumer-intake contract note set",
            },
        );
    }

    if contract
        .chosen_replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_contract_shape
        != LowBoostRecoveryBcReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeContractShapeV1::ReceiptBoundReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::ContractResultMalformed {
                detail: "chosen_replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_contract_shape must remain receipt_bound_replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_only",
            },
        );
    }

    let mut total_specimens = 0usize;
    let mut seen_artifact_ids = BTreeSet::new();

    for (lane_index, lane) in contract.preserved_ordered_lane_results.iter().enumerate() {
        if lane.lane_ordinal != lane_index {
            return Err(
                LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::LaneResultMalformed {
                    lane_index,
                    detail: "lane_ordinal must match lane position",
                },
            );
        }

        if lane.ordered_specimen_results.is_empty() {
            return Err(
                LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::LaneResultMalformed {
                    lane_index,
                    detail: "ordered_specimen_results must not be empty",
                },
            );
        }

        for (specimen_index, specimen) in lane.ordered_specimen_results.iter().enumerate() {
            if specimen.specimen_ordinal != specimen_index {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "specimen_ordinal must match specimen position",
                    },
                );
            }

            let handoff_object = &specimen
                .realized_replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff;
            let consumer_intake_boundary_input = &specimen
                .replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_boundary_input;
            let consumer_intake_output_boundary = &specimen
                .replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_output_boundary;

            if consumer_intake_boundary_input.lane_ordinal != lane.lane_ordinal {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_boundary_input lane_ordinal must match enclosing lane_ordinal",
                    },
                );
            }

            if consumer_intake_boundary_input.specimen_ordinal != specimen.specimen_ordinal {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_boundary_input specimen_ordinal must match specimen_ordinal",
                    },
                );
            }

            let expected_consumer_intake_boundary_input =
                build_low_boost_recovery_bc_receipt_bound_validated_specimen_file_raw_state_window_replay_source_actual_materialization_opaque_handoff_consumer_intake_boundary_input_from_handoff_v1(
                    handoff_object,
                );

            if *consumer_intake_boundary_input != expected_consumer_intake_boundary_input {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_boundary_input must match the exact receipt-bound tuple derived from realized_replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff",
                    },
                );
            }

            if consumer_intake_boundary_input.anchored_bc_specimen_file_path
                == contract.audited_family_root_directory
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_boundary_input anchored_bc_specimen_file_path must remain a specimen file path below audited_family_root_directory",
                    },
                );
            }

            if !consumer_intake_boundary_input
                .anchored_bc_specimen_file_path
                .starts_with(&contract.audited_family_root_directory)
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_boundary_input anchored_bc_specimen_file_path must remain receipt-bound below audited_family_root_directory",
                    },
                );
            }

            if !valid_time_window(
                &consumer_intake_boundary_input.preserved_accepted_reference_window,
            ) {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_boundary_input preserved_accepted_reference_window must remain a valid bounded window",
                    },
                );
            }

            if consumer_intake_boundary_input
                .opaque_caller_admitted_replay_bytes
                .is_empty()
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_boundary_input opaque_caller_admitted_replay_bytes must remain non-empty",
                    },
                );
            }

            let expected_consumer_intake_output_boundary =
                build_low_boost_recovery_bc_receipt_bound_validated_specimen_file_raw_state_window_replay_source_actual_materialization_opaque_handoff_consumer_intake_output_boundary_from_input_v1(
                    consumer_intake_boundary_input,
                );

            if *consumer_intake_output_boundary != expected_consumer_intake_output_boundary {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_output_boundary must match the exact consumer-intake output derived from replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_consumer_intake_boundary_input",
                    },
                );
            }

            if !seen_artifact_ids.insert(consumer_intake_boundary_input.artifact_id.clone()) {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::ContractResultMalformed {
                        detail: "artifact_id values must remain unique across preserved ordered lane results",
                    },
                );
            }

            total_specimens += 1;
        }
    }

    if total_specimens != contract.specimen_count {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowReplaySourceActualMaterializationOpaqueCallerAdmittedReplayByteHandoffConsumerIntakeRealizationError::ContractResultMalformed {
                detail: "specimen_count must equal the number of preserved ordered specimen results",
            },
        );
    }

    Ok(())
}

