#[derive(Debug, Clone, Copy)]
struct LowBoostRecoveryBcActualReplayParsingReplayInputMemoryValidationFailureDetailsV1 {
    file_backed_input: &'static str,
    label_drift: &'static str,
    byte_drift: &'static str,
}

fn validate_low_boost_recovery_bc_actual_replay_parsing_replay_input_memory_for_unsupported_attempt_realization_v1(
    replay_input: &ReplayInput,
    expected_label: &str,
    expected_bytes: &[u8],
    lane_index: usize,
    specimen_index: usize,
    failure_details: LowBoostRecoveryBcActualReplayParsingReplayInputMemoryValidationFailureDetailsV1,
) -> Result<
    (),
    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowActualReplayParsingUnsupportedAttemptRealizationError,
>{
    match replay_input {
        ReplayInput::Memory { label, bytes } => {
            if label != expected_label {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowActualReplayParsingUnsupportedAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: failure_details.label_drift,
                    },
                );
            }

            if bytes != expected_bytes {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowActualReplayParsingUnsupportedAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: failure_details.byte_drift,
                    },
                );
            }
        }
        ReplayInput::File(_) => {
            return Err(
                LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowActualReplayParsingUnsupportedAttemptRealizationError::SpecimenResultMalformed {
                    lane_index,
                    specimen_index,
                    detail: failure_details.file_backed_input,
                },
            );
        }
    }

    Ok(())
}

