fn validate_low_boost_recovery_bc_receipt_bound_specimen_file_existence_readback_validation_result_for_raw_state_materialization_reopen_decision(
    validation: &LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationResultV1,
) -> Result<(), LowBoostRecoveryBcRawStateMaterializationReopenDecisionError> {
    if validation.source_realization_disposition
        != LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationDispositionV1::RealizedForReceiptBoundAnchoredBcSpecimenFilePathOnly
    {
        return Err(
            LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::ValidationResultMalformed {
                detail: "source_realization_disposition must remain realized_for_receipt_bound_anchored_bc_specimen_file_path_only",
            },
        );
    }

    if !matches_exactly_once(
        &validation.source_realization_notes,
        &[
            LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::ReceiptBoundSpecimenFileAnchoredLocatorContractBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::ContractInputsRevalidated,
            LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::AuditedFamilyRootReferencePreservedAsBcSpecimenTreeAnchor,
            LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::LaneAndSpecimenOrderPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::ArtifactIdsPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::SourceRawStateWindowRefsPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::DeterministicRelativeSpecimenFilePathShapeRevalidated,
            LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::ReceiptBoundAnchoredBcSpecimenFilePathRealized,
            LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::SpecimenFileExistenceVerificationDeferred,
            LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::RawStateMaterializationDeferred,
            LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::SidecarManifestAndGenericIndexStillUnjustified,
            LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::MimirExportIntegrationStillForbidden,
        ],
    ) {
        return Err(
            LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::ValidationResultMalformed {
                detail: "source_realization_notes must remain the exact low-boost-recovery receipt-bound specimen-file-anchored raw-state-window locator realization note set",
            },
        );
    }

    if validation.source_chosen_locator_contract_shape
        != LowBoostRecoveryBcReceiptBoundRawStateWindowLocatorContractShapeV1::ReceiptBoundSpecimenFileAnchored
    {
        return Err(
            LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::ValidationResultMalformed {
                detail: "source_chosen_locator_contract_shape must remain receipt_bound_specimen_file_anchored",
            },
        );
    }

    if validation.validation_disposition
        != LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationDispositionV1::ValidatedForReceiptBoundBcSpecimenFileExistenceAndIdentityPreservingReadbackOnly
    {
        return Err(
            LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::ValidationResultMalformed {
                detail: "validation_disposition must remain validated_for_receipt_bound_bc_specimen_file_existence_and_identity_preserving_readback_only",
            },
        );
    }

    if !matches_exactly_once(
        &validation.validation_notes,
        &[
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::ReceiptBoundSpecimenFileAnchoredLocatorRealizationBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::AuditedFamilyRootReferencePreservedAsBcSpecimenTreeAnchor,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::LaneAndSpecimenOrderPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::ArtifactIdsPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::SourceRawStateWindowRefsPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::DeterministicRelativeSpecimenFilePathShapeRevalidated,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::AnchoredBcSpecimenFileExistenceVerified,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::FamilySpecificSpecimenFileReadbackValidated,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::ReadbackIdentityAlignedWithRealizedLocator,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::RawStateMaterializationDeferred,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::SidecarManifestAndGenericIndexStillUnjustified,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::MimirExportIntegrationStillForbidden,
        ],
    ) {
        return Err(
            LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::ValidationResultMalformed {
                detail: "validation_notes must remain the exact low-boost-recovery receipt-bound specimen-file existence/readback validation note set",
            },
        );
    }

    if validation.specimen_count == 0 {
        return Err(
            LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::ValidationResultMalformed {
                detail: "specimen_count must remain greater than zero",
            },
        );
    }

    if validation.group_count == 0 {
        return Err(
            LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::ValidationResultMalformed {
                detail: "group_count must remain greater than zero",
            },
        );
    }

    if validation
        .audited_family_root_directory
        .file_name()
        .and_then(|name| name.to_str())
        != Some(LOW_BOOST_RECOVERY_BC_FILESYSTEM_EXPORT_EMISSION_ROOT_DIRECTORY_V1)
    {
        return Err(
            LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::ValidationResultMalformed {
                detail: "audited_family_root_directory must remain low_boost_recovery_bc_v1",
            },
        );
    }

    if !validation.audited_family_root_directory.exists() {
        return Err(
            LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::ValidationResultMalformed {
                detail: "audited_family_root_directory must exist for raw-state materialization reopen decision",
            },
        );
    }

    if !validation.audited_family_root_directory.is_dir() {
        return Err(
            LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::ValidationResultMalformed {
                detail: "audited_family_root_directory must be a directory for raw-state materialization reopen decision",
            },
        );
    }

    if validation.preserved_ordered_lane_results.is_empty() {
        return Err(
            LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::ValidationResultMalformed {
                detail: "preserved_ordered_lane_results must contain at least one lane result",
            },
        );
    }

    if validation.group_count != validation.preserved_ordered_lane_results.len() {
        return Err(
            LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::ValidationResultMalformed {
                detail: "group_count must equal the number of preserved ordered lane results",
            },
        );
    }

    let mut total_specimens = 0usize;

    for (lane_index, lane) in validation.preserved_ordered_lane_results.iter().enumerate() {
        if lane.lane_ordinal != lane_index {
            return Err(
                LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::LaneResultMalformed {
                    lane_index,
                    detail: "lane_ordinal must match the concrete lane position",
                },
            );
        }

        if lane.ordered_specimen_results.is_empty() {
            return Err(
                LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::LaneResultMalformed {
                    lane_index,
                    detail: "ordered_specimen_results must contain at least one specimen result",
                },
            );
        }

        let expected_lane_directory_name =
            planned_low_boost_recovery_bc_lane_directory_name(lane.lane_ordinal);

        for (specimen_index, specimen) in lane.ordered_specimen_results.iter().enumerate() {
            if specimen.specimen_ordinal != specimen_index {
                return Err(
                    LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "specimen_ordinal must match the concrete specimen position",
                    },
                );
            }

            if specimen.preserved_realized_locator.lane_ordinal != lane.lane_ordinal {
                return Err(
                    LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved realized locator lane_ordinal must match the enclosing lane_ordinal",
                    },
                );
            }

            if specimen.preserved_realized_locator.specimen_ordinal != specimen.specimen_ordinal {
                return Err(
                    LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved realized locator specimen_ordinal must match the enclosing specimen_ordinal",
                    },
                );
            }

            let expected_relative_path = PathBuf::from(&expected_lane_directory_name).join(
                planned_low_boost_recovery_bc_actual_specimen_file_name(
                    &planned_low_boost_recovery_bc_specimen_file_stem(specimen.specimen_ordinal),
                ),
            );
            if specimen
                .preserved_realized_locator
                .deterministic_bc_specimen_file_relative_path
                != expected_relative_path
            {
                return Err(
                    LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "deterministic_bc_specimen_file_relative_path must match the deterministic receipt-bound lane/specimen relative path shape",
                    },
                );
            }

            let expected_anchored_path = validation.audited_family_root_directory.join(
                &specimen
                    .preserved_realized_locator
                    .deterministic_bc_specimen_file_relative_path,
            );
            if specimen
                .preserved_realized_locator
                .anchored_bc_specimen_file_path
                != expected_anchored_path
            {
                return Err(
                    LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "preserved realized locator anchored_bc_specimen_file_path must remain audited_family_root_directory joined with deterministic_bc_specimen_file_relative_path",
                    },
                );
            }

            if !specimen.specimen_file_exists {
                return Err(
                    LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "specimen_file_exists must remain true",
                    },
                );
            }

            if !specimen.readback_matches_realized_locator_identity {
                return Err(
                    LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "readback_matches_realized_locator_identity must remain true",
                    },
                );
            }

            if specimen.readback_specimen.lane_ordinal
                != specimen.preserved_realized_locator.lane_ordinal
            {
                return Err(
                    LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "readback specimen lane_ordinal must match preserved realized locator lane_ordinal",
                    },
                );
            }

            if specimen.readback_specimen.specimen_ordinal
                != specimen.preserved_realized_locator.specimen_ordinal
            {
                return Err(
                    LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "readback specimen specimen_ordinal must match preserved realized locator specimen_ordinal",
                    },
                );
            }

            if specimen.readback_specimen.artifact_id
                != specimen.preserved_realized_locator.artifact_id
            {
                return Err(
                    LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "readback specimen artifact_id must match preserved realized locator artifact_id",
                    },
                );
            }

            if specimen.readback_specimen.source_raw_state_window_ref
                != specimen
                    .preserved_realized_locator
                    .source_raw_state_window_ref
            {
                return Err(
                    LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "readback specimen source_raw_state_window_ref must match preserved realized locator source_raw_state_window_ref",
                    },
                );
            }

            total_specimens += 1;
        }
    }

    if total_specimens != validation.specimen_count {
        return Err(
            LowBoostRecoveryBcRawStateMaterializationReopenDecisionError::ValidationResultMalformed {
                detail: "specimen_count must equal the total number of preserved ordered specimen results",
            },
        );
    }

    Ok(())
}

fn validate_low_boost_recovery_bc_raw_state_materialization_reopen_decision_result_for_receipt_bound_validated_specimen_file_raw_state_window_materialization_contract_definition(
    reopen: &LowBoostRecoveryBcRawStateMaterializationReopenDecisionResultV1,
) -> Result<
    (),
    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError,
>{
    if reopen.source_validation_disposition
        != LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationDispositionV1::ValidatedForReceiptBoundBcSpecimenFileExistenceAndIdentityPreservingReadbackOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "source_validation_disposition must remain validated_for_receipt_bound_bc_specimen_file_existence_and_identity_preserving_readback_only",
            },
        );
    }

    if !matches_exactly_once(
        &reopen.source_validation_notes,
        &[
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::ReceiptBoundSpecimenFileAnchoredLocatorRealizationBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::AuditedFamilyRootReferencePreservedAsBcSpecimenTreeAnchor,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::LaneAndSpecimenOrderPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::ArtifactIdsPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::SourceRawStateWindowRefsPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::DeterministicRelativeSpecimenFilePathShapeRevalidated,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::AnchoredBcSpecimenFileExistenceVerified,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::FamilySpecificSpecimenFileReadbackValidated,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::ReadbackIdentityAlignedWithRealizedLocator,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::RawStateMaterializationDeferred,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::SidecarManifestAndGenericIndexStillUnjustified,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::MimirExportIntegrationStillForbidden,
        ],
    ) {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "source_validation_notes must remain the exact low-boost-recovery receipt-bound specimen-file existence/readback validation note set",
            },
        );
    }

    if reopen.source_chosen_locator_contract_shape
        != LowBoostRecoveryBcReceiptBoundRawStateWindowLocatorContractShapeV1::ReceiptBoundSpecimenFileAnchored
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "source_chosen_locator_contract_shape must remain receipt_bound_specimen_file_anchored",
            },
        );
    }

    if reopen.decision_disposition
        != LowBoostRecoveryBcRawStateMaterializationReopenDispositionV1::ReopenJustifiedForReceiptBoundValidatedSpecimenFileSourceRawStateWindowRefMaterializationContract
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "decision_disposition must remain reopen_justified_for_receipt_bound_validated_specimen_file_source_raw_state_window_ref_materialization_contract",
            },
        );
    }

    if !matches_exactly_once(
        &reopen.decision_notes,
        &[
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::SpecimenFileExistenceReadbackValidationBoundaryPreserved,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::ValidationInputRevalidated,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::AuditedFamilyRootReferencePreservedAsBcSpecimenTreeAnchor,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::ValidatedSpecimenFileIdentityPreserved,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::SourceRawStateWindowRefsPreserved,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::RemainingGapIsReceiptBoundSourceRawStateWindowRefMaterializationBoundaryOnly,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::ReceiptBoundValidatedSpecimenFileSourceRawStateWindowRefMaterializationContractIsMinimumHonestReopen,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::SidecarManifestAndGenericIndexStillUnjustified,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::MimirExportIntegrationStillForbidden,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::TensorAndControlMaterializationStillDeferred,
        ],
    ) {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "decision_notes must remain the exact low-boost-recovery raw-state materialization reopen decision note set",
            },
        );
    }

    if reopen.specimen_count == 0 {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "specimen_count must remain greater than zero",
            },
        );
    }

    if reopen.group_count == 0 {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "group_count must remain greater than zero",
            },
        );
    }

    if reopen
        .audited_family_root_directory
        .file_name()
        .and_then(|name| name.to_str())
        != Some(LOW_BOOST_RECOVERY_BC_FILESYSTEM_EXPORT_EMISSION_ROOT_DIRECTORY_V1)
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "audited_family_root_directory must remain low_boost_recovery_bc_v1",
            },
        );
    }

    if !reopen.audited_family_root_directory.exists() {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "audited_family_root_directory must exist for materialization contract definition",
            },
        );
    }

    if !reopen.audited_family_root_directory.is_dir() {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "audited_family_root_directory must be a directory for materialization contract definition",
            },
        );
    }

    if reopen.chosen_materialization_contract_shape
        != LowBoostRecoveryBcRawStateMaterializationContractShapeV1::ReceiptBoundValidatedSpecimenFileSourceRawStateWindowRefMaterializationAttemptOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::ReopenDecisionResultMalformed {
                detail: "chosen_materialization_contract_shape must remain receipt_bound_validated_specimen_file_source_raw_state_window_ref_materialization_attempt_only",
            },
        );
    }

    Ok(())
}

fn validate_low_boost_recovery_bc_validation_and_reopen_for_receipt_bound_validated_specimen_file_raw_state_window_materialization_contract_definition(
    validation: &LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationResultV1,
    reopen: &LowBoostRecoveryBcRawStateMaterializationReopenDecisionResultV1,
) -> Result<
    (),
    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError,
>{
    validate_low_boost_recovery_bc_receipt_bound_specimen_file_existence_readback_validation_result_for_raw_state_materialization_reopen_decision(
        validation,
    )
    .map_err(|source| {
        LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::ValidationInputRejected {
            source,
        }
    })?;
    validate_low_boost_recovery_bc_raw_state_materialization_reopen_decision_result_for_receipt_bound_validated_specimen_file_raw_state_window_materialization_contract_definition(
        reopen,
    )?;

    if validation.specimen_count != reopen.specimen_count {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::InputMismatch {
                detail: "reopen specimen_count must match validation specimen_count",
            },
        );
    }

    if validation.group_count != reopen.group_count {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::InputMismatch {
                detail: "reopen group_count must match validation group_count",
            },
        );
    }

    if validation.validation_disposition != reopen.source_validation_disposition {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::InputMismatch {
                detail: "reopen source_validation_disposition must match validation_disposition",
            },
        );
    }

    if validation.validation_notes != reopen.source_validation_notes {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::InputMismatch {
                detail: "reopen source_validation_notes must match validation_notes",
            },
        );
    }

    if validation.source_chosen_locator_contract_shape
        != reopen.source_chosen_locator_contract_shape
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::InputMismatch {
                detail: "reopen source_chosen_locator_contract_shape must match validation source_chosen_locator_contract_shape",
            },
        );
    }

    if validation.audited_family_root_directory != reopen.audited_family_root_directory {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDefinitionError::InputMismatch {
                detail: "reopen audited_family_root_directory must match validation audited_family_root_directory",
            },
        );
    }

    Ok(())
}

fn validate_low_boost_recovery_bc_receipt_bound_validated_specimen_file_raw_state_window_materialization_contract_for_attempt_realization(
    contract: &LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractV1,
) -> Result<
    (),
    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError,
>{
    if contract.source_validation_disposition
        != LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationDispositionV1::ValidatedForReceiptBoundBcSpecimenFileExistenceAndIdentityPreservingReadbackOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "source_validation_disposition must remain validated_for_receipt_bound_bc_specimen_file_existence_and_identity_preserving_readback_only",
            },
        );
    }

    if !matches_exactly_once(
        &contract.source_validation_notes,
        &[
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::ReceiptBoundSpecimenFileAnchoredLocatorRealizationBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::AuditedFamilyRootReferencePreservedAsBcSpecimenTreeAnchor,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::LaneAndSpecimenOrderPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::ArtifactIdsPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::SourceRawStateWindowRefsPreserved,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::DeterministicRelativeSpecimenFilePathShapeRevalidated,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::AnchoredBcSpecimenFileExistenceVerified,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::FamilySpecificSpecimenFileReadbackValidated,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::ReadbackIdentityAlignedWithRealizedLocator,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::RawStateMaterializationDeferred,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::SidecarManifestAndGenericIndexStillUnjustified,
            LowBoostRecoveryBcReceiptBoundSpecimenFileExistenceReadbackValidationNoteV1::MimirExportIntegrationStillForbidden,
        ],
    ) {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "source_validation_notes must remain the exact low-boost-recovery receipt-bound specimen-file existence/readback validation note set",
            },
        );
    }

    if contract.source_reopen_decision_disposition
        != LowBoostRecoveryBcRawStateMaterializationReopenDispositionV1::ReopenJustifiedForReceiptBoundValidatedSpecimenFileSourceRawStateWindowRefMaterializationContract
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "source_reopen_decision_disposition must remain reopen_justified_for_receipt_bound_validated_specimen_file_source_raw_state_window_ref_materialization_contract",
            },
        );
    }

    if !matches_exactly_once(
        &contract.source_reopen_decision_notes,
        &[
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::SpecimenFileExistenceReadbackValidationBoundaryPreserved,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::ValidationInputRevalidated,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::AuditedFamilyRootReferencePreservedAsBcSpecimenTreeAnchor,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::ValidatedSpecimenFileIdentityPreserved,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::SourceRawStateWindowRefsPreserved,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::RemainingGapIsReceiptBoundSourceRawStateWindowRefMaterializationBoundaryOnly,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::ReceiptBoundValidatedSpecimenFileSourceRawStateWindowRefMaterializationContractIsMinimumHonestReopen,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::SidecarManifestAndGenericIndexStillUnjustified,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::MimirExportIntegrationStillForbidden,
            LowBoostRecoveryBcRawStateMaterializationReopenNoteV1::TensorAndControlMaterializationStillDeferred,
        ],
    ) {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "source_reopen_decision_notes must remain the exact low-boost-recovery raw-state materialization reopen decision note set",
            },
        );
    }

    if contract.source_chosen_locator_contract_shape
        != LowBoostRecoveryBcReceiptBoundRawStateWindowLocatorContractShapeV1::ReceiptBoundSpecimenFileAnchored
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "source_chosen_locator_contract_shape must remain receipt_bound_specimen_file_anchored",
            },
        );
    }

    if contract.contract_disposition
        != LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractDispositionV1::ContractDefinedForReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "contract_disposition must remain contract_defined_for_receipt_bound_validated_specimen_file_raw_state_window_materialization_attempt_only",
            },
        );
    }

    if !matches_exactly_once(
        &contract.contract_notes,
        &[
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::SpecimenFileExistenceReadbackValidationBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::RawStateMaterializationReopenDecisionBoundaryPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::ValidationAndReopenInputsCrossValidated,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::AuditedFamilyRootReferencePreservedAsBcSpecimenTreeAnchor,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::LaneAndSpecimenOrderPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::ArtifactIdsPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::AnchoredBcSpecimenFilePathsPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::SourceRawStateWindowRefsPreserved,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::ReceiptBoundSourceLineagePreservedForMaterializationAttemptOnly,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::ObservationBindingKindAndAcceptedReferenceWindowPreservedForDeferredObservationAccess,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::ActualRawStateMaterializationDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::ReplayParsingStillDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::TensorAndControlMaterializationStillDeferred,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::SidecarManifestAndGenericIndexStillUnjustified,
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationContractNoteV1::MimirExportIntegrationStillForbidden,
        ],
    ) {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "contract_notes must remain the exact low-boost-recovery receipt-bound validated specimen-file raw-state-window materialization contract note set",
            },
        );
    }

    if contract.specimen_count == 0 {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "specimen_count must remain greater than zero",
            },
        );
    }

    if contract.group_count == 0 {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "group_count must remain greater than zero",
            },
        );
    }

    if contract
        .audited_family_root_directory
        .file_name()
        .and_then(|name| name.to_str())
        != Some(LOW_BOOST_RECOVERY_BC_FILESYSTEM_EXPORT_EMISSION_ROOT_DIRECTORY_V1)
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "audited_family_root_directory must remain low_boost_recovery_bc_v1",
            },
        );
    }

    if !contract.audited_family_root_directory.exists() {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "audited_family_root_directory must exist for materialization attempt realization",
            },
        );
    }

    if !contract.audited_family_root_directory.is_dir() {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "audited_family_root_directory must be a directory for materialization attempt realization",
            },
        );
    }

    if contract.chosen_materialization_contract_shape
        != LowBoostRecoveryBcRawStateMaterializationContractShapeV1::ReceiptBoundValidatedSpecimenFileSourceRawStateWindowRefMaterializationAttemptOnly
    {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "chosen_materialization_contract_shape must remain receipt_bound_validated_specimen_file_source_raw_state_window_ref_materialization_attempt_only",
            },
        );
    }

    if contract.group_count != contract.preserved_ordered_lane_results.len() {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "group_count must equal the number of preserved ordered lane results",
            },
        );
    }

    let mut total_specimens = 0usize;
    let mut seen_artifact_ids = HashSet::new();

    for (lane_index, lane) in contract.preserved_ordered_lane_results.iter().enumerate() {
        if lane.lane_ordinal != lane_index {
            return Err(
                LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::LaneResultMalformed {
                    lane_index,
                    detail: "lane_ordinal must match lane position",
                },
            );
        }

        if lane.ordered_specimen_results.is_empty() {
            return Err(
                LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::LaneResultMalformed {
                    lane_index,
                    detail: "ordered_specimen_results must not be empty",
                },
            );
        }

        for (specimen_index, specimen) in lane.ordered_specimen_results.iter().enumerate() {
            if specimen.specimen_ordinal != specimen_index {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "specimen_ordinal must match specimen position",
                    },
                );
            }

            let admitted = &specimen.admitted_validated_specimen;
            let attempt_input = &specimen.materialization_attempt_input;
            let output_boundary = &specimen.materialization_attempt_output_boundary;

            if admitted.anchored_bc_specimen_file_path == contract.audited_family_root_directory {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "anchored_bc_specimen_file_path must remain a specimen file path below audited_family_root_directory",
                    },
                );
            }

            if !admitted
                .anchored_bc_specimen_file_path
                .starts_with(&contract.audited_family_root_directory)
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "anchored_bc_specimen_file_path must remain receipt-bound below audited_family_root_directory",
                    },
                );
            }

            if attempt_input.lane_ordinal != lane.lane_ordinal {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_input lane_ordinal must match enclosing lane_ordinal",
                    },
                );
            }

            if attempt_input.specimen_ordinal != specimen.specimen_ordinal {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_input specimen_ordinal must match specimen_ordinal",
                    },
                );
            }

            if attempt_input.artifact_id != admitted.artifact_id {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_input artifact_id must match admitted_validated_specimen artifact_id",
                    },
                );
            }

            if attempt_input.anchored_bc_specimen_file_path
                != admitted.anchored_bc_specimen_file_path
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_input anchored_bc_specimen_file_path must match admitted_validated_specimen anchored_bc_specimen_file_path",
                    },
                );
            }

            if attempt_input.source_raw_state_window_ref != admitted.source_raw_state_window_ref {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_input source_raw_state_window_ref must match admitted_validated_specimen source_raw_state_window_ref",
                    },
                );
            }

            if attempt_input.source_slice_id != admitted.source_slice_id {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_input source_slice_id must match admitted_validated_specimen source_slice_id",
                    },
                );
            }

            if attempt_input.source_replay != admitted.source_replay {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_input source_replay must match admitted_validated_specimen source_replay",
                    },
                );
            }

            if attempt_input.source_subject != admitted.source_subject {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_input source_subject must match admitted_validated_specimen source_subject",
                    },
                );
            }

            if attempt_input.source_phase_id != admitted.source_phase_id {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_input source_phase_id must match admitted_validated_specimen source_phase_id",
                    },
                );
            }

            if output_boundary.lane_ordinal != lane.lane_ordinal {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_output_boundary lane_ordinal must match enclosing lane_ordinal",
                    },
                );
            }

            if output_boundary.specimen_ordinal != specimen.specimen_ordinal {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_output_boundary specimen_ordinal must match specimen_ordinal",
                    },
                );
            }

            if output_boundary.artifact_id != attempt_input.artifact_id {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_output_boundary artifact_id must match materialization_attempt_input artifact_id",
                    },
                );
            }

            if output_boundary.anchored_bc_specimen_file_path
                != attempt_input.anchored_bc_specimen_file_path
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_output_boundary anchored_bc_specimen_file_path must match materialization_attempt_input anchored_bc_specimen_file_path",
                    },
                );
            }

            if output_boundary.source_raw_state_window_ref
                != attempt_input.source_raw_state_window_ref
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_output_boundary source_raw_state_window_ref must match materialization_attempt_input source_raw_state_window_ref",
                    },
                );
            }

            if output_boundary.source_slice_id != attempt_input.source_slice_id {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_output_boundary source_slice_id must match materialization_attempt_input source_slice_id",
                    },
                );
            }

            if output_boundary.source_replay != attempt_input.source_replay {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_output_boundary source_replay must match materialization_attempt_input source_replay",
                    },
                );
            }

            if output_boundary.source_subject != attempt_input.source_subject {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_output_boundary source_subject must match materialization_attempt_input source_subject",
                    },
                );
            }

            if output_boundary.source_phase_id != attempt_input.source_phase_id {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_output_boundary source_phase_id must match materialization_attempt_input source_phase_id",
                    },
                );
            }

            if output_boundary.preserved_observation_binding_kind
                != admitted.observation_binding_kind
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_output_boundary preserved_observation_binding_kind must match admitted_validated_specimen observation_binding_kind",
                    },
                );
            }

            if output_boundary.preserved_accepted_reference_window
                != admitted.accepted_reference_window
            {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "materialization_attempt_output_boundary preserved_accepted_reference_window must match admitted_validated_specimen accepted_reference_window",
                    },
                );
            }

            if !seen_artifact_ids.insert(admitted.artifact_id.clone()) {
                return Err(
                    LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::SpecimenResultMalformed {
                        lane_index,
                        specimen_index,
                        detail: "artifact_id must remain unique across preserved ordered specimen results",
                    },
                );
            }

            total_specimens += 1;
        }
    }

    if total_specimens != contract.specimen_count {
        return Err(
            LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowMaterializationAttemptRealizationError::ContractResultMalformed {
                detail: "specimen_count must equal the total number of preserved ordered specimen results",
            },
        );
    }

    Ok(())
}

