    #[test]
    fn low_boost_bc_emitted_output_audit_readback_succeeds_for_valid_emitted_receipt() {
        let plan = accepted_low_boost_bc_filesystem_export_emission_plan_result();
        let directory = tempdir().expect("tempdir should be created");
        let receipt =
            emit_low_boost_recovery_bc_actual_filesystem_emission_v1(&plan, directory.path())
                .expect("valid emission should succeed");

        let audit = audit_readback_low_boost_recovery_bc_emitted_output_v1(&receipt)
            .expect("valid emitted receipt should audit successfully");

        assert_eq!(audit.specimen_count, 3);
        assert_eq!(audit.group_count, 2);
        assert_eq!(
            audit.emitted_family_root_directory,
            receipt.emitted_family_root_directory
        );
        assert!(audit.family_root_directory_exists);
        assert_eq!(
            audit.audit_disposition,
            LowBoostRecoveryBcEmittedOutputAuditReadbackDispositionV1::ReadyForLowBoostRecoveryEmittedOutputRefinementOnly
        );
        assert_eq!(
            audit.audit_notes,
            vec![
                LowBoostRecoveryBcEmittedOutputAuditReadbackNoteV1::ActualFilesystemEmissionReceiptBoundaryPreserved,
                LowBoostRecoveryBcEmittedOutputAuditReadbackNoteV1::EmittedRootLaneSpecimenPathsVerified,
                LowBoostRecoveryBcEmittedOutputAuditReadbackNoteV1::FamilySpecificSpecimenReadbackVerified,
                LowBoostRecoveryBcEmittedOutputAuditReadbackNoteV1::NoAdditionalSemanticsInferredBeyondEmittedContract,
                LowBoostRecoveryBcEmittedOutputAuditReadbackNoteV1::TensorAndControlMaterializationDeferred,
                LowBoostRecoveryBcEmittedOutputAuditReadbackNoteV1::MimirExportIntegrationDeferred,
            ]
        );
        assert_eq!(
            audit.ordered_lane_results.len(),
            receipt.ordered_lane_receipts.len()
        );
        assert_eq!(
            audit.ordered_lane_results[0]
                .ordered_specimen_results
                .iter()
                .map(|specimen| specimen.artifact_id.clone())
                .collect::<Vec<_>>(),
            receipt.ordered_lane_receipts[0]
                .ordered_specimen_receipts
                .iter()
                .map(|specimen| specimen.artifact_id.clone())
                .collect::<Vec<_>>()
        );
        assert!(
            audit
                .ordered_lane_results
                .iter()
                .all(|lane| lane.lane_directory_exists)
        );
        assert!(
            audit
                .ordered_lane_results
                .iter()
                .flat_map(|lane| lane.ordered_specimen_results.iter())
                .all(|specimen| specimen.specimen_file_exists
                    && specimen.readback_matches_receipt_contract)
        );
    }

