    #[test]
    fn low_boost_bc_receipt_bound_specimen_file_anchored_raw_state_window_locator_realization_produces_path_only_receipt_bound_locators()
     {
        let contract =
            accepted_low_boost_bc_receipt_bound_specimen_file_anchored_raw_state_window_locator_contract();

        let result =
            realize_low_boost_recovery_bc_receipt_bound_specimen_file_anchored_raw_state_window_locator_v1(
                &contract,
            )
            .expect("valid contract input should produce a realized locator result");

        assert_eq!(result.specimen_count, contract.specimen_count);
        assert_eq!(result.group_count, contract.group_count);
        assert_eq!(
            result.source_contract_disposition,
            contract.contract_disposition
        );
        assert_eq!(result.source_contract_notes, contract.contract_notes);
        assert_eq!(
            result.source_chosen_locator_contract_shape,
            contract.chosen_locator_contract_shape
        );
        assert_eq!(
            result.audited_family_root_directory,
            contract.audited_family_root_directory
        );
        assert_eq!(
            result.realization_disposition,
            LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationDispositionV1::RealizedForReceiptBoundAnchoredBcSpecimenFilePathOnly
        );
        assert_eq!(
            result.realization_notes,
            vec![
                LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::ReceiptBoundSpecimenFileAnchoredLocatorContractBoundaryPreserved,
                LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::ContractInputsRevalidated,
                LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::AuditedFamilyRootReferencePreservedAsBcSpecimenTreeAnchor,
                LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::LaneAndSpecimenOrderPreserved,
                LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::ArtifactIdsPreserved,
                LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::SourceRawStateWindowRefsPreserved,
                LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::DeterministicRelativeSpecimenFilePathShapeRevalidated,
                LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::ReceiptBoundAnchoredBcSpecimenFilePathRealized,
                LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::SpecimenFileExistenceVerificationDeferred,
                LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::RawStateMaterializationDeferred,
                LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::SidecarManifestAndGenericIndexStillUnjustified,
                LowBoostRecoveryBcReceiptBoundSpecimenFileAnchoredRawStateWindowLocatorRealizationNoteV1::MimirExportIntegrationStillForbidden,
            ]
        );

        let contract_artifact_ids = contract
            .preserved_ordered_lane_results
            .iter()
            .map(|lane| {
                lane.ordered_specimen_results
                    .iter()
                    .map(|specimen| specimen.deterministic_lookup_source.artifact_id.clone())
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        let realized_artifact_ids = result
            .preserved_ordered_lane_results
            .iter()
            .map(|lane| {
                lane.ordered_specimen_results
                    .iter()
                    .map(|specimen| specimen.realized_locator.artifact_id.clone())
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        assert_eq!(realized_artifact_ids, contract_artifact_ids);

        let first_contract_specimen =
            &contract.preserved_ordered_lane_results[0].ordered_specimen_results[0];
        let first_realized_specimen =
            &result.preserved_ordered_lane_results[0].ordered_specimen_results[0];
        assert_eq!(first_realized_specimen.specimen_ordinal, 0);
        assert_eq!(first_realized_specimen.realized_locator.lane_ordinal, 0);
        assert_eq!(
            first_realized_specimen.realized_locator.specimen_ordinal,
            first_contract_specimen.specimen_ordinal
        );
        assert_eq!(
            first_realized_specimen
                .realized_locator
                .deterministic_bc_specimen_file_relative_path,
            first_contract_specimen
                .deterministic_lookup_source
                .deterministic_bc_specimen_file_relative_path
        );
        assert_eq!(
            first_realized_specimen
                .realized_locator
                .anchored_bc_specimen_file_path,
            contract.audited_family_root_directory.join(
                &first_contract_specimen
                    .deterministic_lookup_source
                    .deterministic_bc_specimen_file_relative_path
            )
        );
        assert_eq!(
            first_realized_specimen
                .realized_locator
                .source_raw_state_window_ref,
            first_contract_specimen
                .deterministic_lookup_source
                .source_raw_state_window_ref
        );
    }

