    #[test]
    fn low_boost_bc_receipt_bound_replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_contract_preserves_lane_specimen_order_and_artifact_ids()
     {
        let (_directory, realization) =
            accepted_low_boost_bc_receipt_bound_validated_specimen_file_raw_state_window_replay_source_actual_materialization_byte_backed_caller_admitted_source_form_realization_result();
        let contract =
            define_low_boost_recovery_bc_receipt_bound_validated_specimen_file_raw_state_window_replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_contract_v1(
                &realization,
            )
            .expect("valid byte-backed caller-admitted source-form realization should produce an opaque replay-byte handoff contract");

        let source_artifact_ids = realization
            .preserved_ordered_lane_results
            .iter()
            .map(|lane| {
                lane.ordered_specimen_results
                    .iter()
                    .map(|specimen| {
                        specimen
                            .realized_replay_source_actual_materialization_byte_backed_caller_admitted_source_form
                            .artifact_id
                            .clone()
                    })
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        let contract_artifact_ids = contract
            .preserved_ordered_lane_results
            .iter()
            .map(|lane| {
                lane.ordered_specimen_results
                    .iter()
                    .map(|specimen| {
                        specimen
                            .replay_source_actual_materialization_opaque_caller_admitted_replay_byte_handoff_boundary_input
                            .artifact_id
                            .clone()
                    })
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        assert_eq!(contract_artifact_ids, source_artifact_ids);

        for (lane_index, (realized_lane, contract_lane)) in realization
            .preserved_ordered_lane_results
            .iter()
            .zip(contract.preserved_ordered_lane_results.iter())
            .enumerate()
        {
            assert_eq!(realized_lane.lane_ordinal, lane_index);
            assert_eq!(contract_lane.lane_ordinal, lane_index);

            for (specimen_index, (realized_specimen, contract_specimen)) in realized_lane
                .ordered_specimen_results
                .iter()
                .zip(contract_lane.ordered_specimen_results.iter())
                .enumerate()
            {
                assert_eq!(realized_specimen.specimen_ordinal, specimen_index);
                assert_eq!(contract_specimen.specimen_ordinal, specimen_index);
            }
        }
    }

