    fn load_rl_replay_header_fixture_001_bytes_or_skip() -> Option<Vec<u8>> {
        let path = std::env::var_os("MIMIR_REPLAY_FIXTURE_PATH")
            .map(std::path::PathBuf::from)
            .unwrap_or_else(|| {
                std::path::PathBuf::from(
                    r"D:\RocketLeague bot\MIMIR\external_fixtures\sample_001.replay",
                )
            });

        match std::fs::read(&path) {
            Ok(bytes) => Some(bytes),
            Err(error) => {
                eprintln!(
                    "fixture missing or unreadable at {}; skipping rl_replay_header_fixture_001 fixture-specific mimir-skill seam test: {}",
                    path.display(),
                    error
                );
                None
            }
        }
    }

    fn replay_header_only_bytes_from_fixture(bytes: &[u8]) -> Vec<u8> {
        assert!(
            bytes.len() >= 8,
            "fixture must contain header_size and header_crc fields"
        );
        let header_size = i32::from_le_bytes(
            bytes[0..4]
                .try_into()
                .expect("fixture should contain header_size"),
        );
        assert!(header_size >= 0, "fixture header_size must be non-negative");
        let header_end =
            8 + usize::try_from(header_size).expect("fixture header_size should fit usize");
        assert!(
            header_end <= bytes.len(),
            "fixture header_size must stay within fixture bytes"
        );

        bytes[..header_end].to_vec()
    }

    fn replace_all_actual_replay_parsing_contract_attempt_memory_bytes(
        contract: &mut LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowActualReplayParsingContractV1,
        bytes: &[u8],
    ) {
        for lane in &mut contract.preserved_ordered_lane_results {
            for specimen in &mut lane.ordered_specimen_results {
                replace_actual_replay_parsing_contract_specimen_memory_bytes(specimen, bytes);
            }
        }
    }

    fn replace_actual_replay_parsing_contract_specimen_memory_bytes(
        specimen: &mut LowBoostRecoveryBcReceiptBoundValidatedSpecimenFileRawStateWindowActualReplayParsingContractSpecimenResultV1,
        bytes: &[u8],
    ) {
        specimen
            .consumed_replay_input_creation_from_opaque_caller_admitted_replay_bytes_boundary_input
            .opaque_caller_admitted_replay_bytes = bytes.to_vec();
        specimen
            .preserved_replay_input_creation_from_opaque_caller_admitted_replay_bytes_output_boundary
            .opaque_caller_admitted_replay_bytes = bytes.to_vec();
        replace_replay_input_memory_bytes(
            &mut specimen
                .preserved_replay_input_creation_from_opaque_caller_admitted_replay_bytes_output_boundary
                .created_replay_input,
            bytes,
        );
        specimen
            .preserved_replay_input_creation_from_opaque_caller_admitted_replay_bytes_bridge
            .opaque_caller_admitted_replay_bytes = bytes.to_vec();
        replace_replay_input_memory_bytes(
            &mut specimen
                .preserved_replay_input_creation_from_opaque_caller_admitted_replay_bytes_bridge
                .created_replay_input,
            bytes,
        );
        specimen
            .actual_replay_parsing_attempt_boundary_input
            .opaque_caller_admitted_replay_bytes = bytes.to_vec();
        replace_replay_input_memory_bytes(
            &mut specimen
                .actual_replay_parsing_attempt_boundary_input
                .preserved_replay_input,
            bytes,
        );
        specimen
            .actual_replay_parsing_attempt_output_boundary
            .opaque_caller_admitted_replay_bytes = bytes.to_vec();
        replace_replay_input_memory_bytes(
            &mut specimen
                .actual_replay_parsing_attempt_output_boundary
                .preserved_replay_input,
            bytes,
        );
        specimen
            .actual_replay_parsing_header_attempt
            .opaque_caller_admitted_replay_bytes = bytes.to_vec();
        replace_replay_input_memory_bytes(
            &mut specimen
                .actual_replay_parsing_header_attempt
                .attempt_replay_input,
            bytes,
        );
    }

    fn replace_replay_input_memory_bytes(replay_input: &mut ReplayInput, bytes: &[u8]) {
        match replay_input {
            ReplayInput::Memory {
                bytes: replay_input_bytes,
                ..
            } => {
                *replay_input_bytes = bytes.to_vec();
            }
            ReplayInput::File(path) => panic!(
                "test helper must only update ReplayInput::Memory, found file-backed input: {}",
                path.display()
            ),
        }
    }

